'use client';

import React, { useState, useCallback, useEffect, useMemo } from 'react';
import { AssessmentReport } from '@/lib/mockData';
import {
  TrendingUp,
  Users,
  Target,
  Download,
  Plus,
  ChevronRight,
  Search,
  CheckCircle2,
  HelpCircle,
  FileText,
  BookOpen,
  Trash2,
  Send
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { useAuth } from '@/context/AuthContext';

export default function AnalyticsPage() {
  const { user } = useAuth();
  const [reports, setReports] = useState<AssessmentReport[]>([]);
  const [assessments, setAssessments] = useState<any[]>([]);
  const [submissions, setSubmissions] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [showAllReports, setShowAllReports] = useState(false);
  const [selectedReport, setSelectedReport] = useState<AssessmentReport | null>(null);

  const calculateAnalysis = () => {
    if (reports.length === 0) return [
      { label: 'Exceeded Expectations', value: 0, color: '#10b981' },
      { label: 'Met Expectations', value: 0, color: '#3b82f6' },
      { label: 'Below Average', value: 0, color: '#f59e0b' },
      { label: 'Requires Attention', value: 0, color: '#ef4444' },
    ];

    const counts = { exceeded: 0, met: 0, below: 0, attention: 0 };
    reports.forEach(r => {
      if (r.passingRate >= 90) counts.exceeded++;
      else if (r.passingRate >= 75) counts.met++;
      else if (r.passingRate >= 60) counts.below++;
      else counts.attention++;
    });

    const total = reports.length;
    return [
      { label: 'Exceeded Expectations', value: Math.round((counts.exceeded / total) * 100), color: '#10b981' },
      { label: 'Met Expectations', value: Math.round((counts.met / total) * 100), color: '#3b82f6' },
      { label: 'Below Average', value: Math.round((counts.below / total) * 100), color: '#f59e0b' },
      { label: 'Requires Attention', value: Math.round((counts.attention / total) * 100), color: '#ef4444' },
    ];
  };

  const performanceData = calculateAnalysis();

  const fetchReports = useCallback(async () => {
    try {
      const [reportsRes, assessmentsRes, submissionsRes] = await Promise.all([
        fetch('http://localhost:3001/reports'),
        fetch('http://localhost:3001/assessments'),
        fetch('http://localhost:3001/submissions')
      ]);

      const assessmentsData = await assessmentsRes.json();
      const submissionsData = await submissionsRes.json();

      // Dynamically compute comprehensive performance reports based on actual submissions
      const computedReports = assessmentsData.map((assessment: any) => {
        const relSubmissions = submissionsData.filter((s: any) => s.assessmentId === assessment.id && s.status !== 'Pending');
        const participants = relSubmissions.length;

        const passingCount = relSubmissions.filter((s: any) => s.status === 'Passed' || s.score >= 50).length;
        const passingRate = participants > 0 ? Math.round((passingCount / participants) * 100) : 0;
        const averageScore = participants > 0 ? Math.round(relSubmissions.reduce((acc: number, s: any) => acc + s.score, 0) / participants) : 0;
        const topScore = participants > 0 ? Math.max(...relSubmissions.map((s: any) => s.score)) : 0;

        return {
          id: assessment.id,
          title: assessment.title,
          participants,
          date: assessment.date,
          passingRate,
          averageScore,
          topScore
        };
      }).filter(Boolean);

      setReports(computedReports.reverse());
      setAssessments(assessmentsData);
      setSubmissions(submissionsData);
    } catch (error) {
      console.error('Error fetching dashboard data:', error);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchReports();
  }, [fetchReports]);

  const filteredReports = reports.filter(r =>
    r.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const displayedReports = showAllReports ? filteredReports : filteredReports.slice(0, 3);

  const handleGenerateReport = () => {
    // Generate CSV from reports
    const headers = ['ID', 'Title', 'Participants', 'Date', 'Passing Rate', 'Average Score', 'Top Score'];
    const csvContent = [
      headers.join(','),
      ...reports.map(r => `${r.id},"${r.title}",${r.participants},"${r.date}",${r.passingRate}%,${r.averageScore},${r.topScore}`)
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'assessment_performance_reports.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const totalParticipationsNum = reports.reduce((acc, r) => acc + r.participants, 0);
  const passedCount = reports.reduce((acc, r) => acc + Math.round((r.passingRate / 100) * r.participants), 0);
  const averageSuccessRate = totalParticipationsNum > 0
    ? Math.round((passedCount / totalParticipationsNum) * 100)
    : 0;

  const stats = [
    { label: 'Total Assessments', value: assessments.length.toString(), icon: Target, color: '#3b82f6', trend: '+12%' },
    { label: 'Total Participations', value: totalParticipationsNum.toLocaleString(), icon: Users, color: '#10b981', trend: '+5%' },
    { label: 'Avg. Success Rate', value: `${averageSuccessRate}%`, icon: TrendingUp, color: '#8b5cf6', trend: '+2%' },
  ];

  // Removing previous handleCreateAssessment implementation as it was moved.

  return (
    <div className="animate-premium">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: '3rem' }}>
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '0.5rem' }}>
          </div>
          <h1 style={{ fontSize: '2.5rem', fontWeight: 800, letterSpacing: '-1px', marginBottom: '0.5rem' }}>Performance Analysis</h1>
          <p style={{ color: 'var(--muted-foreground)', fontSize: '1.1rem' }}></p>
        </div>
        <div style={{ display: 'flex', gap: '1rem' }}>
          <button
            onClick={handleGenerateReport}
            className="btn-primary"
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: '0.75rem',
              background: 'var(--admin-primary)',
              boxShadow: '0 10px 20px -5px rgba(30, 64, 175, 0.4)'
            }}
          >
            <Download size={20} />
            Export Data
          </button>
        </div>
      </div>

      {/* Stats Grid */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '2rem', marginBottom: '3rem' }}>
        {stats.map((stat, i) => {
          const Icon = stat.icon;
          return (
            <motion.div
              key={stat.label}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.1 }}
              className="premium-card"
              style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div style={{
                  background: `${stat.color}15`,
                  color: stat.color,
                  padding: '0.8rem',
                  borderRadius: '1rem',
                  boxShadow: `0 8px 16px -4px ${stat.color}20`
                }}>
                  <Icon size={28} />
                </div>
                <div style={{ textAlign: 'right' }}>
                  <span style={{
                    fontSize: '0.75rem',
                    fontWeight: 700,
                    color: 'var(--success)',
                    background: 'rgba(16, 185, 129, 0.1)',
                    padding: '0.3rem 0.75rem',
                    borderRadius: '2rem',
                  }}>
                    {stat.trend}
                  </span>
                  <p style={{ fontSize: '0.8rem', color: 'var(--muted)', marginTop: '0.25rem', fontWeight: 500 }}>vs last month</p>
                </div>
              </div>
              <div>
                <p style={{ fontSize: '1rem', color: 'var(--muted-foreground)', fontWeight: 500, marginBottom: '0.25rem' }}>{stat.label}</p>
                <h3 style={{ fontSize: '2.25rem', fontWeight: 800, letterSpacing: '-0.5px' }}>{stat.value}</h3>
              </div>
            </motion.div>
          );
        })}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'minmax(0, 1.8fr) minmax(0, 1.2fr)', gap: '2rem' }}>
        {/* Reports Table */}
        <div className="premium-card" style={{ padding: '0', overflow: 'hidden', display: 'flex', flexDirection: 'column' }}>
          <div style={{ padding: '2rem', borderBottom: '1px solid var(--card-border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <div style={{ minWidth: 0 }}>
              <h3 style={{ fontSize: '1.25rem', fontWeight: 700, marginBottom: '0.25rem' }}>Assessment Reports</h3>
              <p style={{ fontSize: '0.85rem', color: 'var(--muted-foreground)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>Detailed history of individual test outcomes.</p>
            </div>
            <button
              onClick={() => setShowAllReports(!showAllReports)}
              className="btn-secondary"
              style={{ padding: '0.5rem 1rem', fontSize: '0.85rem', color: 'var(--admin-primary)', fontWeight: 700, whiteSpace: 'nowrap' }}
            >
              {showAllReports ? 'Collapse' : 'See All'}
            </button>
          </div>

          {/* Search Bar */}
          <div style={{ padding: '1rem 1.5rem', background: '#f8fafc' }}>
            <div style={{ position: 'relative' }}>
              <Search size={18} style={{ position: 'absolute', left: '1rem', top: '50%', transform: 'translateY(-50%)', color: 'var(--muted)' }} />
              <input
                placeholder="Find a report..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                style={{
                  width: '100%',
                  padding: '0.75rem 0.75rem 0.75rem 2.75rem',
                  borderRadius: '0.75rem',
                  border: '1px solid #e2e8f0',
                  background: 'white',
                  fontSize: '0.9rem'
                }}
              />
            </div>
          </div>

          <div style={{ padding: '0 1.5rem 1.5rem', overflowX: 'auto' }}>
            {loading ? (
              <div style={{ padding: '3rem', textAlign: 'center', color: 'var(--muted-foreground)' }}>Loading report data...</div>
            ) : reports.length === 0 ? (
              <div style={{ padding: '3rem', textAlign: 'center' }}>
                <FileText size={40} style={{ color: 'var(--muted)', marginBottom: '1rem', opacity: 0.3 }} />
                <p style={{ color: 'var(--muted-foreground)' }}>No reports available.</p>
              </div>
            ) : (
              <table style={{ width: '100%', borderCollapse: 'separate', borderSpacing: '0 0.75rem', minWidth: '600px' }}>
                <thead>
                  <tr style={{ textAlign: 'left', color: 'var(--muted)', fontSize: '0.75rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                    <th style={{ padding: '0 0.75rem' }}>Title</th>
                    <th style={{ padding: '0 0.75rem' }}>Participants</th>
                    <th style={{ padding: '0 0.75rem' }}>Success</th>
                    <th style={{ padding: '0 0.75rem' }}>Avg</th>
                    <th style={{ padding: '0 0.75rem' }}>Top</th>
                    <th style={{ padding: '0 0.75rem' }}></th>
                  </tr>
                </thead>
                <tbody>
                  {displayedReports.map((report) => (
                    <tr
                      key={report.id}
                      className="report-row-premium"
                      style={{ background: '#f8fafc', borderRadius: '0.75rem', cursor: 'pointer', transition: 'all 0.2s' }}
                      onClick={() => setSelectedReport(report)}
                    >
                      <td style={{ padding: '1rem 0.75rem', borderRadius: '0.75rem 0 0 0.75rem' }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                          <div style={{ width: '32px', height: '32px', flexShrink: 0, background: 'white', border: '1px solid #e2e8f0', borderRadius: '8px', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--admin-primary)' }}>
                            <BookOpen size={16} />
                          </div>
                          <div style={{ minWidth: 0 }}>
                            <p style={{ fontWeight: 700, fontSize: '0.9rem', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{report.title}</p>
                            <p style={{ fontSize: '0.7rem', color: 'var(--muted)' }}>{report.date}</p>
                          </div>
                        </div>
                      </td>
                      <td style={{ padding: '1rem 0.75rem' }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', fontWeight: 600, fontSize: '0.9rem' }}>
                          <Users size={14} /> {report.participants}
                        </div>
                      </td>
                      <td style={{ padding: '1rem 0.75rem' }}>
                        <span style={{
                          padding: '0.3rem 0.6rem',
                          borderRadius: '2rem',
                          fontSize: '0.8rem',
                          fontWeight: 700,
                          background: report.passingRate >= 75 ? 'rgba(16, 185, 129, 0.1)' : 'rgba(239, 68, 68, 0.1)',
                          color: report.passingRate >= 75 ? 'var(--success)' : 'var(--destructive)'
                        }}>
                          {report.passingRate}%
                        </span>
                      </td>
                      <td style={{ padding: '1rem 0.75rem', fontWeight: 800, fontSize: '0.9rem' }}>{report.averageScore}</td>
                      <td style={{ padding: '1rem 0.75rem', fontWeight: 800, fontSize: '0.9rem', color: '#f59e0b' }}>{report.topScore}</td>
                      <td style={{ padding: '1rem 0.75rem', borderRadius: '0 0.75rem 0.75rem 0' }}>
                        <div style={{ color: 'var(--admin-primary)' }}>
                          <ChevronRight size={18} />
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        </div>

        {/* Visual Achievement Summary */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem' }}>
          <div className="premium-card">
            <h3 style={{ fontSize: '1.25rem', fontWeight: 700, marginBottom: '2rem' }}>Institution reports</h3>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem' }}>
              {performanceData.map((item) => (
                <div key={item.label}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.9rem', marginBottom: '0.75rem' }}>
                    <span style={{ fontWeight: 600, color: 'var(--secondary)' }}>{item.label}</span>
                    <span style={{ fontWeight: 800, color: item.color }}>{item.value}%</span>
                  </div>
                  <div style={{ height: '12px', background: '#f1f5f9', borderRadius: '6px', overflow: 'hidden', boxShadow: 'inset 0 2px 4px rgba(0,0,0,0.02)' }}>
                    <motion.div
                      initial={{ width: 0 }}
                      animate={{ width: `${item.value}%` }}
                      transition={{ duration: 1.2, ease: [0.16, 1, 0.3, 1] }}
                      style={{
                        height: '100%',
                        background: `linear-gradient(90deg, ${item.color}cc, ${item.color})`,
                        boxShadow: `0 0 10px ${item.color}40`,
                        borderRadius: '6px'
                      }}
                    />
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>


      {/* Selected Report Modal */}
      <AnimatePresence>
        {selectedReport && (
          <div style={{
            position: 'fixed',
            top: 0, left: 0, right: 0, bottom: 0,
            background: 'rgba(2, 6, 23, 0.6)',
            backdropFilter: 'blur(8px)',
            zIndex: 100,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            padding: '2rem'
          }}>
            <motion.div
              initial={{ scale: 0.9, opacity: 0, y: 20 }}
              animate={{ scale: 1, opacity: 1, y: 0 }}
              exit={{ scale: 0.9, opacity: 0, y: 20 }}
              className="premium-card"
              style={{ width: '100%', maxWidth: '540px', padding: '3rem' }}
            >
              <div style={{ textAlign: 'center', marginBottom: '2.5rem' }}>
                <div style={{ width: '64px', height: '64px', background: 'var(--admin-accent)', color: 'var(--admin-primary)', borderRadius: '20px', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1.5rem' }}>
                  <FileText size={32} />
                </div>
                <h2 style={{ fontSize: '1.75rem', fontWeight: 800, marginBottom: '0.5rem', letterSpacing: '-0.5px' }}>Intelligence Report</h2>
                <p style={{ color: 'var(--muted-foreground)', fontSize: '1rem', fontWeight: 500 }}>{selectedReport.title}</p>
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1.5rem', marginBottom: '2.5rem' }}>
                <div style={{ background: '#f8fafc', padding: '1.5rem', borderRadius: '1rem', border: '1px solid #f1f5f9' }}>
                  <p style={{ fontSize: '0.8rem', color: 'var(--muted)', fontWeight: 700, textTransform: 'uppercase', marginBottom: '0.5rem' }}>Participants</p>
                  <h3 style={{ fontSize: '1.75rem', fontWeight: 800, color: 'var(--admin-primary)' }}>{selectedReport.participants}</h3>
                </div>
                <div style={{ background: '#f8fafc', padding: '1.5rem', borderRadius: '1rem', border: '1px solid #f1f5f9' }}>
                  <p style={{ fontSize: '0.8rem', color: 'var(--muted)', fontWeight: 700, textTransform: 'uppercase', marginBottom: '0.5rem' }}>Pass Rate</p>
                  <h3 style={{ fontSize: '1.75rem', fontWeight: 800, color: 'var(--success)' }}>{selectedReport.passingRate}%</h3>
                </div>
                <div style={{ background: '#f8fafc', padding: '1.5rem', borderRadius: '1rem', border: '1px solid #f1f5f9' }}>
                  <p style={{ fontSize: '0.8rem', color: 'var(--muted)', fontWeight: 700, textTransform: 'uppercase', marginBottom: '0.5rem' }}>Avg. Points</p>
                  <h3 style={{ fontSize: '1.75rem', fontWeight: 800 }}>{selectedReport.averageScore}</h3>
                </div>
                <div style={{ background: '#f8fafc', padding: '1.5rem', borderRadius: '1rem', border: '1px solid #f1f5f9' }}>
                  <p style={{ fontSize: '0.8rem', color: 'var(--muted)', fontWeight: 700, textTransform: 'uppercase', marginBottom: '0.5rem' }}>Top Score</p>
                  <h3 style={{ fontSize: '1.75rem', fontWeight: 800, color: '#f59e0b' }}>{selectedReport.topScore}</h3>
                </div>
              </div>

              <div style={{ display: 'flex', gap: '1rem' }}>
                <button
                  onClick={() => setSelectedReport(null)}
                  className="btn-primary"
                  style={{ width: '100%', padding: '1rem', fontWeight: 800, background: 'var(--admin-primary)' }}
                >
                  Confirm & Export Profile
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      <style jsx>{`
        .report-row-premium:hover {
          background-color: #f8fafc;
          transform: translateX(4px);
        }
      `}</style>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Plus, 
  Search, 
  BookOpen, 
  Edit, 
  Trash2, 
  CheckCircle2,
  HelpCircle,
  FileText,
  Send
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { useAuth } from '@/context/AuthContext';

interface Assessment {
  id: string;
  title: string;
  type: string;
  category: string;
  topic: string;
  questionFormats: string[];
  questions?: { 
    id: number; 
    text: string; 
    type: 'MCQ' | 'ShortAnswer' | 'TrueFalse' | 'Essay';
    options?: string[]; 
    correctAnswer?: number 
  }[];
  creatorId: string;
  date: string;
}

export default function AdminAssessments() {
  const { user } = useAuth();
  const [assessments, setAssessments] = useState<Assessment[]>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [showAssignModal, setShowAssignModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingAssessment, setEditingAssessment] = useState<Assessment | null>(null);
  const [selectedAssessment, setSelectedAssessment] = useState<Assessment | null>(null);
  
  // Assignment specific states
  const [studentsList, setStudentsList] = useState<any[]>([]);
  const [selectedAssignee, setSelectedAssignee] = useState('All');

  // Form states
  const [title, setTitle] = useState('');
  const [type, setType] = useState('Quiz');
  const [category, setCategory] = useState('');
  const [topic, setTopic] = useState('');
  const [questions, setQuestions] = useState<{ id: number; text: string; type: 'MCQ' | 'ShortAnswer' | 'TrueFalse' | 'Essay'; options?: string[]; correctAnswer?: number }[]>([]);
  const [formats, setFormats] = useState({
    multipleChoice: true,
    trueFalse: false,
    shortAnswer: false,
    essay: false
  });

  const fetchAssessments = useCallback(async () => {
    try {
      const response = await fetch('http://localhost:3001/assessments');
      const data = await response.json();
      // Admin sees all assessments
      setAssessments(data.reverse());
    } catch (err) {
      console.error('Error fetching assessments:', err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchAssessments();
    
    // Fetch students for assign dropdown
    const getStudents = async () => {
      try {
        const res = await fetch('http://localhost:3001/users?role=student');
        const data = await res.json();
        setStudentsList(data);
      } catch (e) {
        console.error('Failed to load students for assignment:', e);
      }
    };
    getStudents();
  }, [fetchAssessments]);

  const handleSave = async () => {
    if (!title) {
      alert('Please enter a title');
      return;
    }

    const selectedFormats = Object.entries(formats)
      .filter(([, checked]) => checked)
      .map(([name]) => name);

    const assessmentData = {
      id: editingAssessment ? editingAssessment.id : Math.random().toString(36).substring(2, 15),
      title,
      type,
      category,
      topic,
      questionFormats: selectedFormats,
      questions,
      date: new Date().toLocaleDateString('en-CA'),
      creatorId: user?.id || 'admin_1'
    };

    try {
      if (editingAssessment) {
        await fetch(`http://localhost:3001/assessments/${editingAssessment.id}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(assessmentData)
        });
      } else {
        await fetch('http://localhost:3001/assessments', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(assessmentData)
        });
      }
      fetchAssessments();
      closeModal();
    } catch (err) {
      console.error('Error saving assessment:', err);
    }
  };

  const handleDelete = async (id: string) => {
    if (confirm('Are you sure you want to delete this assessment?')) {
      try {
        await fetch(`http://localhost:3001/assessments/${id}`, { method: 'DELETE' });
        fetchAssessments();
      } catch (err) {
        console.error('Error deleting assessment:', err);
      }
    }
  };

  const openEdit = (assessment: Assessment) => {
    setEditingAssessment(assessment);
    setTitle(assessment.title);
    setType(assessment.type);
    setCategory(assessment.category);
    setTopic(assessment.topic);
    setQuestions(assessment.questions || []);
    
    const newFormats = {
      multipleChoice: assessment.questionFormats.includes('multipleChoice'),
      trueFalse: assessment.questionFormats.includes('trueFalse'),
      shortAnswer: assessment.questionFormats.includes('shortAnswer'),
      essay: assessment.questionFormats.includes('essay')
    };
    setFormats(newFormats);
    setShowModal(true);
  };

  const closeModal = () => {
    setShowModal(false);
    setEditingAssessment(null);
    setTitle('');
    setType('Quiz');
    setCategory('');
    setTopic('');
    setQuestions([]);
    setFormats({
      multipleChoice: true,
      trueFalse: false,
      shortAnswer: false,
      essay: false
    });
  };

  const filtered = assessments.filter(a => 
    a.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
    a.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="animate-premium">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: '3rem' }}>
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '0.5rem' }}>
            <span style={{ padding: '0.4rem 0.8rem', background: 'rgba(59, 130, 246, 0.1)', color: 'var(--admin-primary)', borderRadius: '2rem', fontSize: '0.75rem', fontWeight: 700, letterSpacing: '0.05em' }}>
              ADMIN STUDIO
            </span>
          </div>
          <h1 style={{ fontSize: '2.5rem', fontWeight: 800, letterSpacing: '-1px', marginBottom: '0.5rem' }}>Manage Assessment</h1>
        </div>
        <button 
          onClick={() => setShowModal(true)}
          className="btn-primary" 
          style={{ 
            display: 'flex', 
            alignItems: 'center', 
            gap: '0.75rem', 
            background: 'var(--admin-primary)',
            boxShadow: '0 10px 20px -5px rgba(59, 130, 246, 0.4)'
          }}
        >
          <Plus size={20} />
          Launch New
        </button>
      </div>

      <div className="premium-card" style={{ padding: '1.25rem', marginBottom: '2.5rem', display: 'flex', gap: '1.5rem', alignItems: 'center', background: '#f8fafc' }}>
        <div style={{ position: 'relative', flex: 1 }}>
          <Search size={20} style={{ position: 'absolute', left: '1.25rem', top: '50%', transform: 'translateY(-50%)', color: 'var(--muted)' }} />
          <input 
            placeholder="Search all global assessments by title, category or topic..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            style={{ 
              width: '100%',
              padding: '0.85rem 1rem 0.85rem 3.5rem', 
              borderRadius: '1rem',
              border: '1px solid #e2e8f0',
              background: 'white',
              fontSize: '0.95rem'
            }}
          />
        </div>
        <div style={{ height: '30px', width: '1px', background: '#e2e8f0' }} />
        <div style={{ display: 'flex', gap: '0.5rem', alignItems: 'center', color: 'var(--muted-foreground)' }}>
          <Search size={18} />
          <span style={{ fontSize: '0.85rem', fontWeight: 600 }}>Showing {filtered.length} Global Records</span>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(1, 1fr)', gap: '1.25rem' }}>
        {loading ? (
          <div style={{ padding: '4rem', textAlign: 'center', color: 'var(--muted-foreground)' }}>Loading global repository...</div>
        ) : filtered.length === 0 ? (
          <div className="premium-card" style={{ padding: '5rem', textAlign: 'center' }}>
             <BookOpen size={64} style={{ color: 'var(--muted)', marginBottom: '1.5rem', opacity: 0.2 }} />
             <h3 style={{ fontSize: '1.5rem', fontWeight: 700, marginBottom: '0.5rem' }}>No Records Found</h3>
             <p style={{ color: 'var(--muted-foreground)', marginBottom: '2rem' }}>The global assessment repository is currently empty.</p>
             <button onClick={() => setShowModal(true)} className="btn-secondary" style={{ border: 'none', background: 'rgba(59, 130, 246, 0.1)', color: 'var(--admin-primary)', fontWeight: 700 }}>
                Initialize First Protocol
             </button>
          </div>
        ) : (
          filtered.map((a, idx) => (
            <motion.div 
              key={a.id}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: idx * 0.05 }}
              className="premium-card" 
              style={{ display: 'flex', alignItems: 'center', gap: '2rem', padding: '1.75rem 2rem' }}
            >
              <div style={{ 
                width: '60px', height: '60px', 
                background: 'rgba(59, 130, 246, 0.1)', 
                color: 'var(--admin-primary)', 
                borderRadius: '1.25rem', 
                display: 'flex', 
                alignItems: 'center', 
                justifyContent: 'center',
                boxShadow: 'inset 0 2px 4px rgba(0,0,0,0.02)'
              }}>
                <FileText size={28} />
              </div>
              
              <div style={{ flex: 1 }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '0.4rem' }}>
                  <h3 style={{ fontSize: '1.2rem', fontWeight: 700, letterSpacing: '-0.3px' }}>{a.title}</h3>
                  <span style={{ fontSize: '0.75rem', padding: '0.2rem 0.6rem', background: '#f1f5f9', borderRadius: '1rem', fontWeight: 600, color: 'var(--secondary)' }}>{a.type}</span>
                </div>
                <div style={{ display: 'flex', gap: '1.5rem', alignItems: 'center' }}>
                  <p style={{ fontSize: '0.9rem', color: 'var(--muted-foreground)', fontWeight: 500 }}>{a.topic || 'General Topic'}</p>
                  <div style={{ height: '4px', width: '4px', borderRadius: '50%', background: '#cbd5e1' }} />
                  <p style={{ fontSize: '0.85rem', color: 'var(--muted)', fontWeight: 500 }}>Created: {a.date}</p>
                </div>
              </div>

              <div style={{ display: 'flex', gap: '0.5rem' }}>
                {a.questionFormats.slice(0, 3).map(f => (
                  <span key={f} style={{ 
                    fontSize: '0.7rem', padding: '0.3rem 0.75rem', background: 'white', 
                    borderRadius: '2rem', border: '1px solid var(--card-border)', fontWeight: 600, color: 'var(--secondary)'
                  }}>
                    {f.replace(/([A-Z])/g, ' $1').trim()}
                  </span>
                ))}
              </div>

              <div style={{ width: '1px', height: '40px', background: '#f1f5f9', margin: '0 0.5rem' }} />

              <div style={{ display: 'flex', gap: '0.5rem' }}>
                <motion.button 
                  whileHover={{ scale: 1.1 }}
                  whileTap={{ scale: 0.9 }}
                  onClick={() => { setSelectedAssessment(a); setShowAssignModal(true); }}
                  style={{ 
                    width: '44px', height: '44px', borderRadius: '12px', background: 'rgba(59, 130, 246, 0.1)', 
                    color: 'var(--admin-primary)', border: 'none', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer'
                  }}
                  title="Global Assignment"
                >
                  <Send size={18} />
                </motion.button>
                <motion.button 
                  whileHover={{ scale: 1.1 }}
                  whileTap={{ scale: 0.9 }}
                  onClick={() => openEdit(a)} 
                  style={{ 
                    width: '44px', height: '44px', borderRadius: '12px', background: '#f8fafc', 
                    color: 'var(--secondary)', border: '1px solid #e2e8f0', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer'
                  }}
                >
                  <Edit size={18} />
                </motion.button>
                <motion.button 
                  whileHover={{ scale: 1.1, background: '#fee2e2' }}
                  whileTap={{ scale: 0.9 }}
                  onClick={() => handleDelete(a.id)} 
                  style={{ 
                    width: '44px', height: '44px', borderRadius: '12px', background: '#fff1f2', 
                    color: 'var(--destructive)', border: 'none', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer'
                  }}
                >
                  <Trash2 size={18} />
                </motion.button>
              </div>
            </motion.div>
          ))
        )}
      </div>

      {/* Assign Modal */}
      <AnimatePresence>
        {showAssignModal && (
          <div style={{ 
            position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, 
            background: 'rgba(2, 6, 23, 0.5)', backdropFilter: 'blur(8px)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center',
            padding: '2rem'
          }}>
            <motion.div 
              initial={{ opacity: 0, scale: 0.95, y: 20 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 20 }}
              className="premium-card" 
              style={{ width: '100%', maxWidth: '440px', padding: '3rem' }}
            >
              <div style={{ textAlign: 'center', marginBottom: '2.5rem' }}>
                <div className="vibrant-gradient-admin" style={{ 
                  width: '64px', height: '64px', 
                  color: 'white', borderRadius: '20px', display: 'flex', alignItems: 'center', justifyContent: 'center',
                  margin: '0 auto 1.5rem', boxShadow: '0 8px 16px -4px rgba(59, 130, 246, 0.4)'
                }}>
                  <Send size={30} />
                </div>
                <h2 style={{ fontSize: '1.75rem', fontWeight: 800, letterSpacing: '-0.5px', marginBottom: '0.5rem' }}>Global Protocol</h2>
                <p style={{ color: 'var(--muted-foreground)', fontSize: '1rem', fontWeight: 500 }}>{selectedAssessment?.title}</p>
              </div>

              <div style={{ marginBottom: '2rem' }}>
                <label style={{ display: 'block', fontSize: '0.85rem', marginBottom: '0.75rem', fontWeight: 700, color: 'var(--secondary)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                  Target Recipient(s)
                </label>
                <select 
                  className="premium-input"
                  value={selectedAssignee}
                  onChange={e => setSelectedAssignee(e.target.value)}
                  style={{ width: '100%', padding: '1rem', borderRadius: '1rem', border: '1px solid #e2e8f0', fontSize: '1rem', fontWeight: 500 }}
                >
                  <option value="All">All Registered Students</option>
                  {studentsList.map(s => (
                    <option key={s.id} value={s.id}>{s.name} ({s.email})</option>
                  ))}
                </select>
              </div>

              <div style={{ display: 'flex', gap: '1rem' }}>
                <button onClick={() => setShowAssignModal(false)} className="btn-secondary" style={{ flex: 1, border: 'none', background: '#f8fafc', fontWeight: 700 }}>Cancel</button>
                <button 
                  onClick={async () => {
                    try {
                      const targets = selectedAssignee === 'All' 
                        ? studentsList 
                        : studentsList.filter(s => s.id === selectedAssignee);
                      
                      const dateStr = new Date().toLocaleDateString('en-CA');
                      for (const student of targets) {
                        await fetch('http://localhost:3001/submissions', {
                          method: 'POST',
                          headers: { 'Content-Type': 'application/json' },
                          body: JSON.stringify({
                            id: Math.random().toString(36).substring(2, 10),
                            studentName: student.name,
                            assessmentId: selectedAssessment?.id || '',
                            assessmentTitle: selectedAssessment?.title || '',
                            score: 0,
                            status: 'Pending',
                            date: dateStr
                          })
                        });
                      }
                      alert(`Protocol successful! Assigned to ${targets.length} candidates.`);
                      setShowAssignModal(false);
                      setSelectedAssignee('All');
                    } catch (err) {
                      console.error(err);
                      alert('Error assigning assessment');
                    }
                  }} 
                  className="btn-primary" 
                  style={{ flex: 2, background: 'var(--admin-primary)', fontWeight: 800 }}
                >
                  Initialize Protocol
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showModal && (
          <div style={{ 
            position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, 
            background: 'rgba(2, 6, 23, 0.6)', backdropFilter: 'blur(10px)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center',
            padding: '2rem'
          }}>
            <motion.div 
              initial={{ opacity: 0, scale: 0.9, y: 30 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.9, y: 30 }}
              className="premium-card" 
              style={{ width: '100%', maxWidth: '840px', maxHeight: '90vh', overflowY: 'auto', padding: '3.5rem' }}
            >
              <div style={{ marginBottom: '3rem' }}>
                 <h2 style={{ fontSize: '2rem', fontWeight: 800, letterSpacing: '-0.8px', marginBottom: '0.5rem' }}>{editingAssessment ? 'Update Protocol' : 'Create Assessment'}</h2>
                 <p style={{ color: 'var(--muted-foreground)', fontSize: '1rem' }}>Configure global structural details and administrative assessment content.</p>
              </div>
              
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '2rem', marginBottom: '2.5rem' }}>
                <div style={{ gridColumn: 'span 2' }}>
                  <label style={{ display: 'block', fontSize: '0.8rem', marginBottom: '0.75rem', fontWeight: 700, color: 'var(--secondary)', textTransform: 'uppercase' }}>Conceptual Title</label>
                  <input style={{ padding: '1rem', width: '100%', borderRadius: '1rem', border: '1px solid #e2e8f0' }} value={title} onChange={e => setTitle(e.target.value)} placeholder="Ex. Final Semester Coding Exam" />
                </div>
                
                <div>
                  <label style={{ display: 'block', fontSize: '0.8rem', marginBottom: '0.75rem', fontWeight: 700, color: 'var(--secondary)', textTransform: 'uppercase' }}>Assessment Type</label>
                  <select style={{ padding: '1rem', width: '100%', borderRadius: '1rem', border: '1px solid #e2e8f0', background: 'white' }} value={type} onChange={e => setType(e.target.value)}>
                    <option>Quiz</option>
                    <option>Test</option>
                    <option>Exam</option>
                    <option>Survey</option>
                  </select>
                </div>

                <div>
                  <label style={{ display: 'block', fontSize: '0.8rem', marginBottom: '0.75rem', fontWeight: 700, color: 'var(--secondary)', textTransform: 'uppercase' }}>Academic Category</label>
                  <input style={{ padding: '1rem', width: '100%', borderRadius: '1rem', border: '1px solid #e2e8f0' }} value={category} onChange={e => setCategory(e.target.value)} placeholder="Ex. Computer Science" />
                </div>

                <div style={{ gridColumn: 'span 2' }}>
                  <label style={{ display: 'block', fontSize: '0.8rem', marginBottom: '0.75rem', fontWeight: 700, color: 'var(--secondary)', textTransform: 'uppercase' }}>Primary Subject Topic</label>
                  <input style={{ padding: '1rem', width: '100%', borderRadius: '1rem', border: '1px solid #e2e8f0' }} value={topic} onChange={e => setTopic(e.target.value)} placeholder="Ex. Algorithms and Data Structures" />
                </div>
              </div>

              <div style={{ marginBottom: '3rem' }}>
                <label style={{ display: 'block', fontSize: '0.8rem', marginBottom: '1.25rem', fontWeight: 700, color: 'var(--secondary)', textTransform: 'uppercase' }}>Allowed Question Formats</label>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1.25rem' }}>
                  {[
                    { id: 'multipleChoice', label: 'Multiple Choice', icon: CheckCircle2 },
                    { id: 'trueFalse', label: 'True / False', icon: HelpCircle },
                    { id: 'shortAnswer', label: 'Short Answer', icon: FileText },
                    { id: 'essay', label: 'Essay Question', icon: BookOpen },
                  ].map((f) => {
                    const Icon = f.icon;
                    const isChecked = formats[f.id as keyof typeof formats];
                    return (
                      <label key={f.id} style={{ 
                        display: 'flex', alignItems: 'center', gap: '1rem', padding: '1.25rem',
                        background: isChecked ? 'rgba(59, 130, 246, 0.05)' : '#f8fafc',
                        border: `2px solid ${isChecked ? 'var(--admin-primary)' : 'transparent'}`,
                        borderRadius: '1.25rem', cursor: 'pointer', transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
                        boxShadow: isChecked ? '0 8px 16px -4px rgba(59, 130, 246, 0.2)' : 'none'
                      }}>
                        <input 
                          type="checkbox" 
                          style={{ width: '20px', height: '20px', accentColor: 'var(--admin-primary)' }} 
                          checked={isChecked}
                          onChange={e => setFormats({...formats, [f.id]: e.target.checked})}
                        />
                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', flex: 1 }}>
                          <Icon size={20} color={isChecked ? 'var(--admin-primary)' : 'var(--muted)'} />
                          <span style={{ fontSize: '1rem', fontWeight: 600, color: isChecked ? 'var(--admin-primary)' : 'var(--foreground)' }}>{f.label}</span>
                        </div>
                      </label>
                    );
                  })}
                </div>
              </div>

              <div style={{ marginBottom: '3rem', borderTop: '1px solid #f1f5f9', paddingTop: '3rem' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2.5rem' }}>
                  <div>
                    <h3 style={{ fontSize: '1.5rem', fontWeight: 800 }}>Question Architecture</h3>
                    <p style={{ fontSize: '0.9rem', color: 'var(--muted-foreground)', marginTop: '0.2rem' }}>Define individual challenges for this global protocol.</p>
                  </div>
                  <button 
                    onClick={() => setQuestions([...questions, { id: Date.now(), text: '', type: 'MCQ', options: ['', '', '', ''], correctAnswer: 0 }])}
                    className="btn-primary" style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', background: 'var(--admin-primary)', padding: '0.75rem 1.25rem' }}
                  >
                    <Plus size={20} /> Add Challenge
                  </button>
                </div>

                {questions.length === 0 ? (
                  <div style={{ padding: '4rem', textAlign: 'center', background: '#f8fafc', borderRadius: '1.5rem', color: 'var(--muted)', border: '2px dashed #e2e8f0' }}>
                    <Plus size={40} style={{ margin: '0 auto 1.5rem', opacity: 0.3 }} />
                    <p style={{ fontWeight: 600 }}>No active questions. Begin by adding a challenge above.</p>
                  </div>
                ) : (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem' }}>
                    {questions.map((q, qIndex) => (
                      <motion.div 
                        layout
                        initial={{ opacity: 0, scale: 0.98 }}
                        animate={{ opacity: 1, scale: 1 }}
                        key={q.id} 
                        style={{ padding: '2rem', background: 'white', borderRadius: '1.5rem', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgba(0,0,0,0.02)' }}
                      >
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
                          <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
                            <span style={{ width: '30px', height: '30px', background: 'var(--foreground)', color: 'white', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '0.85rem', fontWeight: 800 }}>{qIndex + 1}</span>
                            <select 
                              value={q.type || 'MCQ'} 
                              onChange={e => {
                                 const newQ = [...questions];
                                 const type = e.target.value as 'MCQ' | 'ShortAnswer' | 'TrueFalse' | 'Essay';
                                 newQ[qIndex].type = type;
                                 if (type === 'ShortAnswer' || type === 'Essay') {
                                   newQ[qIndex].options = [];
                                   newQ[qIndex].correctAnswer = undefined;
                                 } else if (type === 'TrueFalse') {
                                   newQ[qIndex].options = ['True', 'False'];
                                   newQ[qIndex].correctAnswer = 0;
                                 } else {
                                   newQ[qIndex].options = ['', '', '', ''];
                                   newQ[qIndex].correctAnswer = 0;
                                 }
                                 setQuestions(newQ);
                              }}
                              style={{ padding: '0.4rem 0.75rem', fontSize: '0.85rem', borderRadius: '0.75rem', fontWeight: 600, border: '1px solid #cbd5e1', background: '#f8fafc' }}
                            >
                              <option value="MCQ">Multiple Choice</option>
                              <option value="TrueFalse">True / False</option>
                              <option value="ShortAnswer">Short Answer</option>
                              <option value="Essay">Essay Question</option>
                            </select>
                          </div>
                          <button onClick={() => setQuestions(questions.filter((_, i) => i !== qIndex))} style={{ color: 'var(--destructive)', background: '#fff1f2', border: 'none', padding: '0.5rem', borderRadius: '0.5rem', cursor: 'pointer' }}>
                            <Trash2 size={18} />
                          </button>
                        </div>

                        <textarea 
                          value={q.text} 
                          onChange={e => { const newQ = [...questions]; newQ[qIndex].text = e.target.value; setQuestions(newQ); }}
                          placeholder="State the problem or question..."
                          rows={2}
                          style={{ width: '100%', marginBottom: '1.5rem', padding: '1rem', background: '#f8fafc', borderRadius: '1rem', border: '1px solid #e2e8f0', fontSize: '1rem', fontWeight: 500 }}
                        />

                        {q.type === 'ShortAnswer' || q.type === 'Essay' ? (
                          <div style={{ padding: '1.5rem', background: 'rgba(59, 130, 246, 0.04)', borderRadius: '1rem', border: '2px dashed #bfdbfe', color: '#1e40af', display: 'flex', alignItems: 'center', gap: '1rem' }}>
                            <HelpCircle size={24} style={{ opacity: 0.5 }} />
                            <p style={{ fontSize: '0.9rem', fontWeight: 600 }}>{q.type === 'Essay' ? 'Reflective Essay - Requires manual scoring.' : 'Direct Short Answer - Requires manual scoring.'}</p>
                          </div>
                        ) : q.type === 'TrueFalse' ? (
                          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1.25rem' }}>
                            {['True', 'False'].map((opt, optIndex) => (
                              <label key={optIndex} style={{ 
                                display: 'flex', alignItems: 'center', gap: '1rem', padding: '1.25rem', 
                                background: q.correctAnswer === optIndex ? 'rgba(59, 130, 246, 0.05)' : '#f8fafc', 
                                borderRadius: '1rem', border: `2px solid ${q.correctAnswer === optIndex ? 'var(--admin-primary)' : 'transparent'}`, 
                                cursor: 'pointer', transition: 'all 0.2s'
                              }}>
                                <input 
                                  type="radio" 
                                  name={`correct-${q.id}`} 
                                  checked={q.correctAnswer === optIndex} 
                                  onChange={() => { const newQ = [...questions]; newQ[qIndex].correctAnswer = optIndex; setQuestions(newQ); }}
                                  style={{ width: '20px', height: '20px', accentColor: 'var(--admin-primary)' }}
                                />
                                <span style={{ fontSize: '1rem', fontWeight: 600 }}>{opt}</span>
                              </label>
                            ))}
                          </div>
                        ) : (
                          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1.25rem' }}>
                            {(q.options || []).map((opt, optIndex) => (
                              <div key={optIndex} style={{ 
                                display: 'flex', alignItems: 'center', gap: '1rem', padding: '0.75rem 1.25rem', 
                                background: '#f8fafc', borderRadius: '1.25rem', border: q.correctAnswer === optIndex ? '2px solid var(--admin-primary)' : '1px solid #e2e8f0',
                                boxShadow: q.correctAnswer === optIndex ? '0 4px 12px rgba(59, 130, 246, 0.1)' : 'none'
                              }}>
                                <input 
                                  type="radio" 
                                  name={`correct-${q.id}`} 
                                  checked={q.correctAnswer === optIndex} 
                                  onChange={() => { const newQ = [...questions]; newQ[qIndex].correctAnswer = optIndex; setQuestions(newQ); }}
                                  style={{ width: '20px', height: '20px', accentColor: 'var(--admin-primary)' }}
                                />
                                <input 
                                  value={opt}
                                  onChange={e => { const newQ = [...questions]; newQ[qIndex].options![optIndex] = e.target.value; setQuestions(newQ); }}
                                  placeholder={`Conceptual Choice ${optIndex + 1}`}
                                  style={{ width: '100%', padding: '0.4rem', background: 'transparent', border: 'none', boxShadow: 'none', fontWeight: 600 }}
                                />
                              </div>
                            ))}
                          </div>
                        )}
                      </motion.div>
                    ))}
                  </div>
                )}
              </div>

              <div style={{ display: 'flex', gap: '1.25rem', justifyContent: 'flex-end', borderTop: '1px solid #f1f5f9', paddingTop: '3rem' }}>
                <button onClick={closeModal} className="btn-secondary" style={{ padding: '0.85rem 2rem', fontWeight: 700, border: 'none', background: '#f1f5f9' }}>Close Studio</button>
                <button 
                  onClick={handleSave} 
                  className="btn-primary" 
                  style={{ padding: '0.85rem 3rem', background: 'var(--admin-primary)', fontWeight: 800, boxShadow: '0 10px 20px -5px rgba(59, 130, 246, 0.4)' }}
                >
                  {editingAssessment ? 'Confirm Protocol Update' : 'Initialize Global Protocol'}
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

'use client';

import React from 'react';
import { useAuth } from '@/context/AuthContext';
import { useRouter, usePathname } from 'next/navigation';
import { 
  Users, 
  BarChart2, 
  LogOut, 
  ShieldCheck,
  Bell,
  BookOpen
} from 'lucide-react';
import { motion } from 'framer-motion';

export default function AdminLayout({ children }: { children: React.ReactNode }) {
  const { logout, user } = useAuth();
  const pathname = usePathname();
  const router = useRouter();

  const menuItems = [
    { name: 'User Management', icon: Users, path: '/admin/users' },
    { name: 'Manage Assessments', icon: BookOpen, path: '/admin/assessments' },
    { name: 'Analytics', icon: BarChart2, path: '/admin/analytics' },
