          width: '280px',
          padding: '2rem 1.25rem',
          display: 'flex',
          flexDirection: 'column',
          position: 'fixed',
          height: '100vh',
          zIndex: 50,
          border: 'none',
          boxShadow: '10px 0 30px -15px rgba(0,0,0,0.05)'
