        <nav style={{ flex: 1 }}>
          <p style={{ fontSize: '0.7rem', color: 'var(--muted)', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: '1.25rem', padding: '0 0.75rem' }}>
