        </nav>

        <div style={{ marginTop: 'auto', paddingTop: '2rem' }}>
          <button
            onClick={logout}
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: '1rem',
              width: '100%',
              padding: '1rem 1.25rem',
              borderRadius: '1rem',
              color: 'var(--destructive)',
              background: 'rgba(239, 68, 68, 0.05)',
              border: 'none',
              cursor: 'pointer',
              fontWeight: 600,
              transition: 'all 0.2s'
            }}
            onMouseOver={(e) => (e.currentTarget.style.background = 'rgba(239, 68, 68, 0.1)')}
            onMouseOut={(e) => (e.currentTarget.style.background = 'rgba(239, 68, 68, 0.05)')}
          >
            <LogOut size={20} />
            Logout
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main style={{ flex: 1, marginLeft: '280px', padding: '0' }}>
        {/* Header */}
        <header style={{
          height: '80px',
          background: 'rgba(255, 255, 255, 0.5)',
          backdropFilter: 'blur(12px)',
          borderBottom: '1px solid var(--card-border)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          padding: '0 3rem',
          position: 'sticky',
          top: 0,
          zIndex: 40
        }}>
          <div style={{ color: 'var(--muted-foreground)', fontSize: '0.9rem', fontWeight: 500 }}>
             Dashboard / <span style={{ color: 'var(--foreground)', fontWeight: 600 }}>{pathname.split('/').pop()?.replace(/^\w/, c => c.toUpperCase())}</span>
          </div>

          <div style={{ display: 'flex', alignItems: 'center', gap: '2rem' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
              <div style={{ textAlign: 'right' }}>
                <p style={{ fontSize: '0.9rem', fontWeight: 700, color: 'var(--foreground)' }}>{user?.name || 'Administrator'}</p>
                <p style={{ fontSize: '0.7rem', color: 'var(--muted)', fontWeight: 600, textTransform: 'uppercase' }}>Super Admin</p>
              </div>
              <div 
                className="vibrant-gradient-admin"
                style={{ 
                  width: '44px', 
                  height: '44px', 
                  borderRadius: '14px', 
                  color: 'white',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  fontWeight: 700,
                  fontSize: '1.1rem',
                  boxShadow: '0 8px 16px -4px rgba(30, 64, 175, 0.2)'
                }}
              >
                {user?.name?.[0].toUpperCase() || 'A'}
              </div>
            </div>
          </div>
        </header>

        {/* Page Content */}
        <div style={{ padding: '3rem', maxWidth: '1400px', margin: '0 auto' }}>
          <motion.div
            initial={{ opacity: 0, scale: 0.98 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: 0.5, ease: [0.16, 1, 0.3, 1] }}
          >
            {children}
          </motion.div>
        </div>
      </main>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import {
  Plus,
  Search,
  BookOpen,
  Filter,
  Edit,
  Trash2,
  CheckCircle2,
  HelpCircle,
  FileText,
  Send
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { useAuth } from '@/context/AuthContext';

interface Assessment {
  id: string;
  title: string;
  type: string;
  category: string;
  topic: string;
  questionFormats: string[];
  questions?: {
    id: number;
    text: string;
    type: 'MCQ' | 'ShortAnswer' | 'TrueFalse' | 'Essay';
    options?: string[];
    correctAnswer?: number
  }[];
  creatorId: string;
  date: string;
}

export default function ManageAssessments() {
  const { user } = useAuth();
  const [assessments, setAssessments] = useState<Assessment[]>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [showAssignModal, setShowAssignModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingAssessment, setEditingAssessment] = useState<Assessment | null>(null);
  const [selectedAssessment, setSelectedAssessment] = useState<Assessment | null>(null);

  // Assignment specific states
  const [studentsList, setStudentsList] = useState<any[]>([]);
  const [selectedAssignee, setSelectedAssignee] = useState('All');

  // Form states
  const [title, setTitle] = useState('');
  const [type, setType] = useState('Quiz');
  const [category, setCategory] = useState('');
  const [topic, setTopic] = useState('');
  const [questions, setQuestions] = useState<{ id: number; text: string; type: 'MCQ' | 'ShortAnswer' | 'TrueFalse' | 'Essay'; options?: string[]; correctAnswer?: number }[]>([]);
  const [formats, setFormats] = useState({
    multipleChoice: true,
    trueFalse: false,
    shortAnswer: false,
    essay: false
  });

  const fetchAssessments = useCallback(async () => {
    try {
      const response = await fetch('http://localhost:3001/assessments');
      const data = await response.json();
      // Filter only assessments created by this educator
      const myData = data.filter((a: Assessment) => a.creatorId === user?.id);
      setAssessments(myData.reverse());
    } catch (err) {
      console.error('Error fetching assessments:', err);
    } finally {
      setLoading(false);
    }
  }, [user]);

  useEffect(() => {
    if (user) fetchAssessments();

    // Fetch students for assign dropdown
    const getStudents = async () => {
      try {
        const res = await fetch('http://localhost:3001/users?role=student');
        const data = await res.json();
        setStudentsList(data);
      } catch (e) {
        console.error('Failed to load students for assignment:', e);
      }
    };
    getStudents();
  }, [user, fetchAssessments]);

  const handleSave = async () => {
    if (!title) {
      alert('Please enter a title');
      return;
    }

    const selectedFormats = Object.entries(formats)
      .filter(([, checked]) => checked)
      .map(([name]) => name);

    const assessmentData = {
      id: Math.random().toString(36).substring(2, 15),
      title,
      type,
      category,
      topic,
      questionFormats: selectedFormats,
      questions,
      date: new Date().toLocaleDateString('en-CA'),
      creatorId: user?.id || 'educator_1'
    };

    try {
      if (editingAssessment) {
        await fetch(`http://localhost:3001/assessments/${editingAssessment.id}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ ...editingAssessment, title, type, category, topic, questionFormats: selectedFormats, questions })
        });
      } else {
        await fetch('http://localhost:3001/assessments', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(assessmentData)
        });
      }
      fetchAssessments();
      closeModal();
    } catch (err) {
      console.error('Error saving assessment:', err);
    }
  };

  const handleDelete = async (id: string) => {
    if (confirm('Are you sure you want to delete this assessment?')) {
      try {
        await fetch(`http://localhost:3001/assessments/${id}`, { method: 'DELETE' });
        fetchAssessments();
      } catch (err) {
        console.error('Error deleting assessment:', err);
      }
    }
  };

  const openEdit = (assessment: Assessment) => {
    setEditingAssessment(assessment);
    setTitle(assessment.title);
    setType(assessment.type);
    setCategory(assessment.category);
    setTopic(assessment.topic);
    setQuestions(assessment.questions || []);

    const newFormats = {
      multipleChoice: assessment.questionFormats.includes('multipleChoice'),
      trueFalse: assessment.questionFormats.includes('trueFalse'),
      shortAnswer: assessment.questionFormats.includes('shortAnswer'),
      essay: assessment.questionFormats.includes('essay')
    };
    setFormats(newFormats);
    setShowModal(true);
  };

  const closeModal = () => {
    setShowModal(false);
    setEditingAssessment(null);
    setTitle('');
    setType('Quiz');
    setCategory('');
    setTopic('');
    setQuestions([]);
    setFormats({
      multipleChoice: true,
      trueFalse: false,
      shortAnswer: false,
      essay: false
    });
  };

  const filtered = assessments.filter(a =>
    a.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
    a.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="animate-premium">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: '3rem' }}>
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '0.5rem' }}>
            <span style={{ padding: '0.4rem 0.8rem', background: 'var(--educator-accent)', color: 'var(--educator-primary)', borderRadius: '2rem', fontSize: '0.75rem', fontWeight: 700, letterSpacing: '0.05em' }}>
              ASSESSMENT MANAGEMENTS
            </span>
          </div>
          <h1 style={{ fontSize: '2.5rem', fontWeight: 800, letterSpacing: '-1px', marginBottom: '0.5rem' }}>Manage assessment</h1>
          <p style={{ color: 'var(--muted-foreground)', fontSize: '1.1rem' }}>Create, organize and assign assessments.</p>
        </div>
        <button
          onClick={() => setShowModal(true)}
          className="btn-primary"
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: '0.75rem',
            background: 'var(--educator-primary)',
            boxShadow: '0 10px 20px -5px rgba(5, 150, 105, 0.4)'
          }}
        >
          <Plus size={20} />
          Create assessments
        </button>
      </div>

      <div className="premium-card" style={{ padding: '1.25rem', marginBottom: '2.5rem', display: 'flex', gap: '1.5rem', alignItems: 'center', background: '#f8fafc' }}>
        <div style={{ position: 'relative', flex: 1 }}>
          <Search size={20} style={{ position: 'absolute', left: '1.25rem', top: '50%', transform: 'translateY(-50%)', color: 'var(--muted)' }} />
          <input
            placeholder="Search by assessment title, category or topic..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            style={{
              width: '100%',
              padding: '0.85rem 1rem 0.85rem 3.5rem',
              borderRadius: '1rem',
              border: '1px solid #e2e8f0',
              background: 'white',
              fontSize: '0.95rem'
            }}
          />
        </div>
        <div style={{ height: '30px', width: '1px', background: '#e2e8f0' }} />
        <div style={{ display: 'flex', gap: '0.5rem', alignItems: 'center', color: 'var(--muted-foreground)' }}>
          <Filter size={18} />
          <span style={{ fontSize: '0.85rem', fontWeight: 600 }}>Showing {filtered.length} Assessments</span>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(1, 1fr)', gap: '1.25rem' }}>
        {loading ? (
          <div style={{ padding: '4rem', textAlign: 'center', color: 'var(--muted-foreground)' }}>Loading your studio...</div>
        ) : filtered.length === 0 ? (
          <div className="premium-card" style={{ padding: '5rem', textAlign: 'center' }}>
            <BookOpen size={64} style={{ color: 'var(--muted)', marginBottom: '1.5rem', opacity: 0.2 }} />
            <h3 style={{ fontSize: '1.5rem', fontWeight: 700, marginBottom: '0.5rem' }}>No Assessments Found</h3>
            <p style={{ color: 'var(--muted-foreground)', marginBottom: '2rem' }}>Start by creating your first interactive assessment.</p>
            <button onClick={() => setShowModal(true)} className="btn-secondary" style={{ border: 'none', background: 'var(--educator-accent)', color: 'var(--educator-primary)', fontWeight: 700 }}>
              Get Started
            </button>
          </div>
        ) : (
          filtered.map((a, idx) => (
            <motion.div
              key={a.id}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: idx * 0.05 }}
              className="premium-card"
              style={{ display: 'flex', alignItems: 'center', gap: '2rem', padding: '1.75rem 2rem' }}
            >
              <div style={{
                width: '60px', height: '60px',
                background: 'var(--educator-accent)',
                color: 'var(--educator-primary)',
                borderRadius: '1.25rem',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                boxShadow: 'inset 0 2px 4px rgba(0,0,0,0.02)'
              }}>
                <FileText size={28} />
              </div>

              <div style={{ flex: 1 }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '0.4rem' }}>
                  <h3 style={{ fontSize: '1.2rem', fontWeight: 700, letterSpacing: '-0.3px' }}>{a.title}</h3>
                  <span style={{ fontSize: '0.75rem', padding: '0.2rem 0.6rem', background: '#f1f5f9', borderRadius: '1rem', fontWeight: 600, color: 'var(--secondary)' }}>{a.type}</span>
                </div>
                <div style={{ display: 'flex', gap: '1.5rem', alignItems: 'center' }}>
                  <p style={{ fontSize: '0.9rem', color: 'var(--muted-foreground)', fontWeight: 500 }}>{a.topic}</p>
                  <div style={{ height: '4px', width: '4px', borderRadius: '50%', background: '#cbd5e1' }} />
                  <p style={{ fontSize: '0.85rem', color: 'var(--muted)', fontWeight: 500 }}>Created on {a.date}</p>
                </div>
              </div>

              <div style={{ display: 'flex', gap: '0.5rem' }}>
                {a.questionFormats.slice(0, 3).map(f => (
                  <span key={f} style={{
                    fontSize: '0.7rem', padding: '0.3rem 0.75rem', background: 'white',
                    borderRadius: '2rem', border: '1px solid var(--card-border)', fontWeight: 600, color: 'var(--secondary)'
                  }}>
                    {f.replace(/([A-Z])/g, ' $1').trim()}
                  </span>
                ))}
                {a.questionFormats.length > 3 && <span style={{ fontSize: '0.7rem', padding: '0.3rem', color: 'var(--muted)' }}>+{a.questionFormats.length - 3} more</span>}
              </div>

              <div style={{ width: '1px', height: '40px', background: '#f1f5f9', margin: '0 0.5rem' }} />

              <div style={{ display: 'flex', gap: '0.5rem' }}>
                <motion.button
                  whileHover={{ scale: 1.1 }}
                  whileTap={{ scale: 0.9 }}
                  onClick={() => { setSelectedAssessment(a); setShowAssignModal(true); }}
                  style={{
                    width: '44px', height: '44px', borderRadius: '12px', background: 'var(--educator-accent)',
                    color: 'var(--educator-primary)', border: 'none', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer'
                  }}
                  title="Assign Assessment"
                >
                  <Send size={18} />
                </motion.button>
                <motion.button
                  whileHover={{ scale: 1.1 }}
                  whileTap={{ scale: 0.9 }}
                  onClick={() => openEdit(a)}
                  style={{
                    width: '44px', height: '44px', borderRadius: '12px', background: '#f8fafc',
                    color: 'var(--secondary)', border: '1px solid #e2e8f0', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer'
                  }}
                >
                  <Edit size={18} />
                </motion.button>
                <motion.button
                  whileHover={{ scale: 1.1, background: '#fee2e2' }}
                  whileTap={{ scale: 0.9 }}
                  onClick={() => handleDelete(a.id)}
                  style={{
                    width: '44px', height: '44px', borderRadius: '12px', background: '#fff1f2',
                    color: 'var(--destructive)', border: 'none', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer'
                  }}
                >
                  <Trash2 size={18} />
                </motion.button>
              </div>
            </motion.div>
          ))
        )}
      </div>

      {/* Assign Modal */}
      <AnimatePresence>
        {showAssignModal && (
          <div style={{
            position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
            background: 'rgba(2, 6, 23, 0.5)', backdropFilter: 'blur(8px)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center',
            padding: '2rem'
          }}>
            <motion.div
              initial={{ opacity: 0, scale: 0.95, y: 20 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 20 }}
              className="premium-card"
              style={{ width: '100%', maxWidth: '440px', padding: '3rem' }}
            >
              <div style={{ textAlign: 'center', marginBottom: '2.5rem' }}>
                <div className="vibrant-gradient-educator" style={{
                  width: '64px', height: '64px',
                  color: 'white', borderRadius: '20px', display: 'flex', alignItems: 'center', justifyContent: 'center',
                  margin: '0 auto 1.5rem', boxShadow: '0 8px 16px -4px rgba(5, 150, 105, 0.4)'
                }}>
                  <Send size={30} />
                </div>
                <h2 style={{ fontSize: '1.75rem', fontWeight: 800, letterSpacing: '-0.5px', marginBottom: '0.5rem' }}>Publish Content</h2>
                <p style={{ color: 'var(--muted-foreground)', fontSize: '1rem', fontWeight: 500 }}>{selectedAssessment?.title}</p>
              </div>

              <div style={{ marginBottom: '2rem' }}>
                <label style={{ display: 'block', fontSize: '0.85rem', marginBottom: '0.75rem', fontWeight: 700, color: 'var(--secondary)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                  Target Audience
                </label>
                <select
                  className="premium-input"
                  value={selectedAssignee}
                  onChange={e => setSelectedAssignee(e.target.value)}
                  style={{ width: '100%', padding: '1rem', borderRadius: '1rem', border: '1px solid #e2e8f0', fontSize: '1rem', fontWeight: 500 }}
                >
                  <option value="All">All Active Students</option>
                  {studentsList.map(s => (
                    <option key={s.id} value={s.id}>{s.name} ({s.email})</option>
                  ))}
                </select>
              </div>

              <div style={{ display: 'flex', gap: '1rem' }}>
                <button onClick={() => setShowAssignModal(false)} className="btn-secondary" style={{ flex: 1, border: 'none', background: '#f8fafc', fontWeight: 700 }}>Cancel</button>
                <button
                  onClick={async () => {
                    try {
                      const targets = selectedAssignee === 'All'
                        ? studentsList
                        : studentsList.filter(s => s.id === selectedAssignee);

                      for (const student of targets) {
                        await fetch('http://localhost:3001/submissions', {
                          method: 'POST',
                          headers: { 'Content-Type': 'application/json' },
                          body: JSON.stringify({
                            id: Math.random().toString(36).substring(2, 10),
                            studentName: student.name,
                            assessmentId: selectedAssessment?.id || '',
                            assessmentTitle: selectedAssessment?.title || '',
                            score: 0,
                            status: 'Pending',
                            date: new Date().toLocaleDateString('en-CA')
                          })
                        });
                      }
                      alert(`Published to ${targets.length} student(s) successfully!`);
                      setShowAssignModal(false);
                      setSelectedAssignee('All');
                    } catch (err) {
                      console.error(err);
                      alert('Error assigning assessment');
                    }
                  }}
                  className="btn-primary"
                  style={{ flex: 2, background: 'var(--educator-primary)', fontWeight: 800 }}
                >
                  Publish Now
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showModal && (
          <div style={{
            position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
            background: 'rgba(2, 6, 23, 0.6)', backdropFilter: 'blur(10px)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center',
            padding: '2rem'
          }}>
            <motion.div
              initial={{ opacity: 0, scale: 0.9, y: 30 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.9, y: 30 }}
              className="premium-card"
              style={{ width: '100%', maxWidth: '840px', maxHeight: '90vh', overflowY: 'auto', padding: '3.5rem' }}
            >
              <div style={{ marginBottom: '3rem' }}>
                <h2 style={{ fontSize: '2rem', fontWeight: 800, letterSpacing: '-0.8px', marginBottom: '0.5rem' }}>{editingAssessment ? 'Update Masterpiece' : 'Design Assessment'}</h2>
                <p style={{ color: 'var(--muted-foreground)', fontSize: '1rem' }}>Configure the structural details and content of your assessment.</p>
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '2rem', marginBottom: '2.5rem' }}>
                <div style={{ gridColumn: 'span 2' }}>
                  <label style={{ display: 'block', fontSize: '0.8rem', marginBottom: '0.75rem', fontWeight: 700, color: 'var(--secondary)', textTransform: 'uppercase' }}> Title</label>
                  <input style={{ padding: '1rem', width: '100%', borderRadius: '1rem', border: '1px solid #e2e8f0' }} value={title} onChange={e => setTitle(e.target.value)} placeholder="Ex. Advanced Algorithmic Complexity" />
                </div>

                <div>
                  <label style={{ display: 'block', fontSize: '0.8rem', marginBottom: '0.75rem', fontWeight: 700, color: 'var(--secondary)', textTransform: 'uppercase' }}>Assessment Type</label>
                  <select style={{ padding: '1rem', width: '100%', borderRadius: '1rem', border: '1px solid #e2e8f0', background: 'white' }} value={type} onChange={e => setType(e.target.value)}>
                    <option>Quiz</option>
                    <option>Test</option>
                    <option>Exam</option>
                    <option>Survey</option>
                  </select>
                </div>

                <div>
                  <label style={{ display: 'block', fontSize: '0.8rem', marginBottom: '0.75rem', fontWeight: 700, color: 'var(--secondary)', textTransform: 'uppercase' }}>Academic Category</label>
                  <input style={{ padding: '1rem', width: '100%', borderRadius: '1rem', border: '1px solid #e2e8f0' }} value={category} onChange={e => setCategory(e.target.value)} placeholder="Ex. Computer Science" />
                </div>

                <div style={{ gridColumn: 'span 2' }}>
                  <label style={{ display: 'block', fontSize: '0.8rem', marginBottom: '0.75rem', fontWeight: 700, color: 'var(--secondary)', textTransform: 'uppercase' }}>Primary Subject Topic</label>
                  <input style={{ padding: '1rem', width: '100%', borderRadius: '1rem', border: '1px solid #e2e8f0' }} value={topic} onChange={e => setTopic(e.target.value)} placeholder="Ex. Big O Notation & Runtime Analysis" />
                </div>
              </div>

              <div style={{ marginBottom: '3rem' }}>
                <label style={{ display: 'block', fontSize: '0.8rem', marginBottom: '1.25rem', fontWeight: 700, color: 'var(--secondary)', textTransform: 'uppercase' }}>Supported Question Architecture</label>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1.25rem' }}>
                  {[
                    { id: 'multipleChoice', label: 'Multiple Choice', icon: CheckCircle2 },
                    { id: 'trueFalse', label: 'True / False', icon: HelpCircle },
                    { id: 'shortAnswer', label: 'Short Answer', icon: FileText },
                    { id: 'essay', label: 'Essay Question', icon: BookOpen },
                  ].map((f) => {
                    const Icon = f.icon;
                    const isChecked = formats[f.id as keyof typeof formats];
                    return (
                      <label key={f.id} style={{
                        display: 'flex', alignItems: 'center', gap: '1rem', padding: '1.25rem',
                        background: isChecked ? 'var(--educator-accent)' : '#f8fafc',
                        border: `2px solid ${isChecked ? 'var(--educator-primary)' : 'transparent'}`,
                        borderRadius: '1.25rem', cursor: 'pointer', transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
                        boxShadow: isChecked ? '0 8px 16px -4px rgba(5, 150, 105, 0.2)' : 'none'
                      }}>
                        <input
                          type="checkbox"
                          style={{ width: '20px', height: '20px', accentColor: 'var(--educator-primary)' }}
                          checked={isChecked}
                          onChange={e => setFormats({ ...formats, [f.id]: e.target.checked })}
                        />
                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', flex: 1 }}>
                          <Icon size={20} color={isChecked ? 'var(--educator-primary)' : 'var(--muted)'} />
                          <span style={{ fontSize: '1rem', fontWeight: 600, color: isChecked ? 'var(--educator-primary)' : 'var(--foreground)' }}>{f.label}</span>
                        </div>
                      </label>
                    );
                  })}
                </div>
              </div>

              <div style={{ marginBottom: '3rem', borderTop: '1px solid #f1f5f9', paddingTop: '3rem' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2.5rem' }}>
                  <div>
                    <h3 style={{ fontSize: '1.5rem', fontWeight: 800 }}>Questions</h3>
                    <p style={{ fontSize: '0.9rem', color: 'var(--muted-foreground)', marginTop: '0.2rem' }}>Define individual challenges for your students.</p>
                  </div>
                  <button
                    onClick={() => setQuestions([...questions, { id: Date.now(), text: '', type: 'MCQ', options: ['', '', '', ''], correctAnswer: 0 } as any])}
                    className="btn-primary" style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', background: 'var(--educator-primary)', padding: '0.75rem 1.25rem' }}
                  >
                    <Plus size={20} /> Add questions
                  </button>
                </div>

                {questions.length === 0 ? (
                  <div style={{ padding: '4rem', textAlign: 'center', background: '#f8fafc', borderRadius: '1.5rem', color: 'var(--muted)', border: '2px dashed #e2e8f0' }}>
                    <Plus size={40} style={{ margin: '0 auto 1.5rem', opacity: 0.3 }} />
                    <p style={{ fontWeight: 600 }}>No active questions. Begin by adding a challenge above.</p>
                  </div>
                ) : (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem' }}>
                    {questions.map((q, qIndex) => (
                      <motion.div
                        layout
                        initial={{ opacity: 0, scale: 0.98 }}
                        animate={{ opacity: 1, scale: 1 }}
                        key={q.id}
                        style={{ padding: '2rem', background: 'white', borderRadius: '1.5rem', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgba(0,0,0,0.02)' }}
                      >
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
                          <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
                            <span style={{ width: '30px', height: '30px', background: 'var(--foreground)', color: 'white', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '0.85rem', fontWeight: 800 }}>{qIndex + 1}</span>
                            <select
                              value={q.type || 'MCQ'}
                              onChange={e => {
                                const newQ = [...questions];
                                const type = e.target.value as 'MCQ' | 'ShortAnswer' | 'TrueFalse' | 'Essay';
                                newQ[qIndex].type = type;
                                if (type === 'ShortAnswer' || type === 'Essay') {
                                  newQ[qIndex].options = [];
                                  newQ[qIndex].correctAnswer = undefined;
                                } else if (type === 'TrueFalse') {
                                  newQ[qIndex].options = ['True', 'False'];
                                  newQ[qIndex].correctAnswer = 0;
                                } else {
                                  newQ[qIndex].options = ['', '', '', ''];
                                  newQ[qIndex].correctAnswer = 0;
                                }
                                setQuestions(newQ as any);
                              }}
                              style={{ padding: '0.4rem 0.75rem', fontSize: '0.85rem', borderRadius: '0.75rem', fontWeight: 600, border: '1px solid #cbd5e1', background: '#f8fafc' }}
                            >
                              <option value="MCQ">Multiple Choice</option>
                              <option value="TrueFalse">True / False</option>
                              <option value="ShortAnswer">Short Answer</option>
                              <option value="Essay">Essay Question</option>
                            </select>
                          </div>
                          <button onClick={() => setQuestions(questions.filter((_, i) => i !== qIndex))} style={{ color: 'var(--destructive)', background: '#fff1f2', border: 'none', padding: '0.5rem', borderRadius: '0.5rem', cursor: 'pointer' }}>
                            <Trash2 size={18} />
                          </button>
                        </div>

                        <textarea
                          value={q.text}
                          onChange={e => { const newQ = [...questions]; newQ[qIndex].text = e.target.value; setQuestions(newQ as any); }}
                          placeholder="State the problem or question..."
                          rows={2}
                          style={{ width: '100%', marginBottom: '1.5rem', padding: '1rem', background: '#f8fafc', borderRadius: '1rem', border: '1px solid #e2e8f0', fontSize: '1rem', fontWeight: 500 }}
                        />

                        {q.type === 'ShortAnswer' || q.type === 'Essay' ? (
                          <div style={{ padding: '1.5rem', background: 'rgba(59, 130, 246, 0.04)', borderRadius: '1rem', border: '2px dashed #bfdbfe', color: '#1e40af', display: 'flex', alignItems: 'center', gap: '1rem' }}>
                            <HelpCircle size={24} style={{ opacity: 0.5 }} />
                            <p style={{ fontSize: '0.9rem', fontWeight: 600 }}>{q.type === 'Essay' ? 'Reflective Essay - Requires manual scoring.' : 'Direct Short Answer - Requires manual scoring.'}</p>
                          </div>
                        ) : q.type === 'TrueFalse' ? (
                          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1.25rem' }}>
                            {['True', 'False'].map((opt, optIndex) => (
                              <label key={optIndex} style={{
                                display: 'flex', alignItems: 'center', gap: '1rem', padding: '1.25rem',
                                background: q.correctAnswer === optIndex ? 'var(--educator-accent)' : '#f8fafc',
                                borderRadius: '1rem', border: `2px solid ${q.correctAnswer === optIndex ? 'var(--educator-primary)' : 'transparent'}`,
                                cursor: 'pointer', transition: 'all 0.2s'
                              }}>
                                <input
                                  type="radio"
                                  name={`correct-${q.id}`}
                                  checked={q.correctAnswer === optIndex}
                                  onChange={() => { const newQ = [...questions]; newQ[qIndex].correctAnswer = optIndex; setQuestions(newQ as any); }}
                                  style={{ width: '20px', height: '20px', accentColor: 'var(--educator-primary)' }}
                                />
                                <span style={{ fontSize: '1rem', fontWeight: 600 }}>{opt}</span>
                              </label>
                            ))}
                          </div>
                        ) : (
                          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1.25rem' }}>
                            {(q.options || []).map((opt, optIndex) => (
                              <div key={optIndex} style={{
                                display: 'flex', alignItems: 'center', gap: '1rem', padding: '0.75rem 1.25rem',
                                background: '#f8fafc', borderRadius: '1.25rem', border: q.correctAnswer === optIndex ? '2px solid var(--educator-primary)' : '1px solid #e2e8f0',
                                boxShadow: q.correctAnswer === optIndex ? '0 4px 12px rgba(5, 150, 105, 0.1)' : 'none'
                              }}>
                                <input
                                  type="radio"
                                  name={`correct-${q.id}`}
                                  checked={q.correctAnswer === optIndex}
                                  onChange={() => { const newQ = [...questions]; newQ[qIndex].correctAnswer = optIndex; setQuestions(newQ as any); }}
                                  style={{ width: '20px', height: '20px', accentColor: 'var(--educator-primary)' }}
                                />
                                <input
                                  value={opt}
                                  onChange={e => { const newQ = [...questions]; newQ[qIndex].options![optIndex] = e.target.value; setQuestions(newQ as any); }}
                                  placeholder={`Conceptual Choice ${optIndex + 1}`}
                                  style={{ width: '100%', padding: '0.4rem', background: 'transparent', border: 'none', boxShadow: 'none', fontWeight: 600 }}
                                />
                              </div>
                            ))}
                          </div>
                        )}
                      </motion.div>
                    ))}
                  </div>
                )}
              </div>

              <div style={{ display: 'flex', gap: '1.25rem', justifyContent: 'flex-end', borderTop: '1px solid #f1f5f9', paddingTop: '3rem' }}>
                <button onClick={closeModal} className="btn-secondary" style={{ padding: '0.85rem 2rem', fontWeight: 700, border: 'none', background: '#f1f5f9' }}>Close</button>
                <button
                  onClick={handleSave}
                  className="btn-primary"
                  style={{ padding: '0.85rem 3rem', background: 'var(--educator-primary)', fontWeight: 800, boxShadow: '0 10px 20px -5px rgba(5, 150, 105, 0.4)' }}
                >
                  {editingAssessment ? 'Confirm Structural Update' : 'submit'}
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Users, 
  BookOpen, 
  CheckCircle, 
  Clock
} from 'lucide-react';
import { motion } from 'framer-motion';
import { useAuth } from '@/context/AuthContext';

interface Assessment {
  id: string;
  title: string;
  type: string;
  category: string;
  topic: string;
  questionFormats: string[];
  creatorId: string;
  date: string;
}

interface Submission {
  id: string;
  studentName: string;
  assessmentTitle: string;
  score: number;
  status: string;
  date: string;
}

export default function EducatorDashboard() {
  const { user } = useAuth();
  const [loading, setLoading] = useState(true);
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  
  const [stats, setStats] = useState([
    { label: 'My Assessments', value: '0', icon: BookOpen, color: '#10b981', trend: 'Live' },
    { label: 'Active Students', value: '0', icon: Users, color: '#3b82f6', trend: 'Live' },
    { label: 'Completed Tests', value: '0', icon: CheckCircle, color: '#8b5cf6', trend: 'Live' },
    { label: 'Avg. Score', value: '0%', icon: Clock, color: '#f59e0b', trend: 'Live' },
  ]);

  const fetchDashboardData = useCallback(async () => {
    try {
      setLoading(true);
      
      // Fetch Assessments
      const aRes = await fetch('http://localhost:3001/assessments');
      const allAssessments = await aRes.json();
      const myAssessments = allAssessments.filter((a: Assessment) => a.creatorId === user?.id);

      // Fetch Students
      const uRes = await fetch('http://localhost:3001/users?role=student');
      const students = await uRes.json();

      // Fetch Submissions
      const sRes = await fetch('http://localhost:3001/submissions');
      const allSubmissions = await sRes.json();
      
      // Filter submissions for user's assessments
      const myAssessmentTitles = myAssessments.map((a: Assessment) => a.title);
      const mySubmissions = allSubmissions.filter((s: Submission) => myAssessmentTitles.includes(s.assessmentTitle));
      setSubmissions(mySubmissions.reverse());

      // Calculate Avg Score
      const avgScore = mySubmissions.length > 0
        ? Math.round(mySubmissions.reduce((acc: number, curr: Submission) => acc + curr.score, 0) / mySubmissions.length)
        : 0;

      setStats([
        { label: 'My Assessments', value: myAssessments.length.toString(), icon: BookOpen, color: '#10b981', trend: 'Live Data' },
        { label: 'Active Students', value: students.filter((s: any) => s.status === 'active').length.toString(), icon: Users, color: '#3b82f6', trend: 'Live Data' },
        { label: 'Completed Tests', value: mySubmissions.length.toString(), icon: CheckCircle, color: '#8b5cf6', trend: 'Live Data' },
        { label: 'Avg. Score', value: `${avgScore}%`, icon: Clock, color: '#f59e0b', trend: 'Live Data' },
      ]);

    } catch (err) {
      console.error('Error fetching dashboard data:', err);
    } finally {
      setLoading(false);
    }
  }, [user]);

  useEffect(() => {
    fetchDashboardData();
  }, [user, fetchDashboardData]);

  return (
    <div className="animate-fade-in">
      <div style={{ marginBottom: '2.5rem' }}>
        <h1 style={{ fontSize: '2rem', fontWeight: 700, marginBottom: '0.5rem' }}>Instructor Dashboard</h1>
        <p style={{ color: 'var(--muted-foreground)' }}>Welcome back! Here&apos;s what&apos;s happening with your assessments today.</p>
      </div>

      {/* Stats Grid */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '1.5rem', marginBottom: '3rem' }}>
        {stats.map((stat, i) => {
          const Icon = stat.icon;
          return (
            <motion.div 
              key={stat.label}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.1 }}
              className="card" 
              style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                <div style={{ 
                  background: `${stat.color}15`, 
                  color: stat.color, 
                  padding: '0.6rem', 
                  borderRadius: '0.75rem' 
                }}>
                  <Icon size={24} />
                </div>
                <span style={{ 
                  fontSize: '0.75rem', 
                  fontWeight: 600, 
                  color: stat.color,
                  background: `${stat.color}10`,
                  padding: '0.2rem 0.6rem',
                  borderRadius: '1rem'
                }}>
                  {stat.trend}
                </span>
              </div>
              <div>
                <p style={{ fontSize: '0.9rem', color: 'var(--muted-foreground)', marginBottom: '0.25rem' }}>{stat.label}</p>
                <h3 style={{ fontSize: '1.75rem', fontWeight: 700 }}>{stat.value}</h3>
              </div>
            </motion.div>
          );
        })}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr', gap: '2rem' }}>
        {/* Recent Submissions */}
        <div className="card" style={{ padding: '0' }}>
          <div style={{ padding: '1.5rem', borderBottom: '1px solid var(--card-border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <h3 style={{ fontSize: '1.1rem' }}>Recent Student Submissions</h3>
            <button style={{ fontSize: '0.85rem', color: '#10b981', fontWeight: 600, background: 'none' }}>View All Submissions</button>
          </div>
          <div style={{ padding: '0.5rem 1.5rem' }}>
            {loading ? (
              <div style={{ padding: '2rem', textAlign: 'center', color: 'var(--muted-foreground)' }}>Loading data...</div>
            ) : submissions.length === 0 ? (
              <div style={{ padding: '2rem', textAlign: 'center', color: 'var(--muted-foreground)' }}>No recent submissions.</div>
            ) : (
              submissions.slice(0, 4).map((sub, i) => (
                <div 
                  key={i} 
                  style={{ 
                    padding: '1.25rem 0', 
                    borderBottom: i === Math.min(submissions.length, 4) - 1 ? 'none' : '1px solid var(--card-border)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between'
                  }}
                >
                  <div style={{ display: 'flex', gap: '1rem', alignItems: 'center' }}>
                    <div style={{ 
                      width: '40px', 
                      height: '40px', 
                      background: 'var(--accent)', 
                      borderRadius: '50%',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      fontWeight: 600,
                      fontSize: '0.8rem'
                    }}>
                      {sub.studentName.split(' ').map((n: string) => n[0]).join('')}
                    </div>
                    <div>
                      <h4 style={{ fontSize: '0.95rem', fontWeight: 600 }}>{sub.studentName}</h4>
                      <p style={{ fontSize: '0.8rem', color: 'var(--muted-foreground)' }}>Completed: {sub.assessmentTitle}</p>
                    </div>
                  </div>
                  <div style={{ textAlign: 'right' }}>
                    <p style={{ fontSize: '0.95rem', fontWeight: 700, color: sub.score >= 70 ? '#10b981' : '#f59e0b' }}>{sub.score}%</p>
                    <p style={{ fontSize: '0.75rem', color: 'var(--muted-foreground)' }}>{sub.date}</p>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Users, 
  CheckCircle, 
  Search, 
  Download,
  TrendingUp,
  Edit3,
  X,
  CheckCircle2,
  AlertCircle,
  Clock
} from 'lucide-react';
import { motion } from 'framer-motion';
import { useAuth } from '@/context/AuthContext';

interface Submission {
  id: string;
  studentName: string;
  assessmentTitle: string;
  score: number;
  status: string;
  date: string;
  assessmentId?: string;
  feedbackGiven: boolean;
  answers?: Record<string, number>;
}

interface Assessment {
  id: string;
  title: string;
  creatorId: string;
}

export default function StudentResults() {
  const { user } = useAuth();
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [stats, setStats] = useState([
    { label: 'Total Submissions', value: '0', icon: Users, color: '#3b82f6' },
    { label: 'Avg. Score', value: '0%', icon: TrendingUp, color: '#10b981' },
  ]);
  
  // Valuation Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [evaluatingSubmission, setEvaluatingSubmission] = useState<Submission | null>(null);
  const [evaluatingAssessment, setEvaluatingAssessment] = useState<any>(null);
  const [valuationScore, setValuationScore] = useState<number>(0);
  const [valuationStatus, setValuationStatus] = useState<string>('Passed');
  const [manualMarks, setManualMarks] = useState<Record<string, boolean>>({});
  const [isSaving, setIsSaving] = useState(false);
  const [hasMounted, setHasMounted] = useState(false);

  useEffect(() => {
    setHasMounted(true);
  }, []);

  const fetchResults = useCallback(async () => {
    try {
      const aRes = await fetch('http://localhost:3001/assessments');
      const allAssessments = await aRes.json();
      const myAssessmentTitles = allAssessments
        .filter((a: Assessment) => a.creatorId === user?.id)
        .map((a: Assessment) => a.title);

      const response = await fetch('http://localhost:3001/submissions');
      const allSubmissions = await response.json();
      
      const mySubmissions = allSubmissions.filter((s: Submission) => 
        myAssessmentTitles.includes(s.assessmentTitle)
      );
      
      setSubmissions(mySubmissions.reverse());

      // Calculate Stats
      const avgScore = mySubmissions.length > 0
        ? Math.round(mySubmissions.reduce((acc: number, curr: Submission) => acc + curr.score, 0) / mySubmissions.length)
        : 0;

      setStats([
        { label: 'Total Submissions', value: mySubmissions.length.toString(), icon: Users, color: '#3b82f6' },
        { label: 'Avg. Score', value: `${avgScore}%`, icon: TrendingUp, color: '#10b981' },
      ]);
    } catch (err) {
      console.error('Error fetching results:', err);
    }
  }, [user]);

  const handleEvaluate = async (submission: Submission) => {
    setEvaluatingSubmission(submission);
    setValuationScore(submission.score);
    setValuationStatus(submission.status);
    setIsModalOpen(true);

    try {
      let response;
      if (submission.assessmentId) {
        response = await fetch(`http://localhost:3001/assessments/${submission.assessmentId}`);
        const data = await response.json();
        if (data) {
          setEvaluatingAssessment(data);
          // Pre-populate manual marks for MCQs based on auto-correct if needed
          const initialMarks: Record<string, boolean> = {};
          data.questions?.forEach((q: any) => {
            if (q.type === 'MCQ') {
               initialMarks[q.id] = (submission.answers?.[q.id] === q.correctAnswer);
            }
          });
          setManualMarks(initialMarks);
        }
      } else {
        response = await fetch(`http://localhost:3001/assessments?title=${encodeURIComponent(submission.assessmentTitle)}`);
        const data = await response.json();
        if (data.length > 0) {
          setEvaluatingAssessment(data[0]);
          const initialMarks: Record<string, boolean> = {};
          data[0].questions?.forEach((q: any) => {
            if (q.type === 'MCQ') {
               initialMarks[q.id] = (submission.answers?.[q.id] === q.correctAnswer);
            }
          });
          setManualMarks(initialMarks);
        }
      }
    } catch (err) {
      console.error('Error fetching assessment details:', err);
    }
  };

  const handleSaveValuation = async () => {
    if (!evaluatingSubmission) return;
    setIsSaving(true);

    try {
      await fetch(`http://localhost:3001/submissions/${evaluatingSubmission.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          score: valuationScore,
          status: valuationStatus
        })
      });
      setIsModalOpen(false);
      fetchResults();
    } catch (err) {
      console.error('Error saving valuation:', err);
      alert('Failed to save valuation.');
    } finally {
      setIsSaving(false);
    }
  };

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    if (user) fetchResults();
  }, [user, fetchResults]);

  const filtered = submissions.filter(s => 
    s.studentName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.assessmentTitle.toLowerCase().includes(searchTerm.toLowerCase())
  ).sort((a, b) => {
    // Priority 1: Submitted ones come first
    if (a.status === 'Submitted' && b.status !== 'Submitted') return -1;
    if (a.status !== 'Submitted' && b.status === 'Submitted') return 1;
    // Priority 2: Newest date first
    return new Date(b.date).getTime() - new Date(a.date).getTime();
  });

  if (!hasMounted) return null;

  return (
    <div className="animate-fade-in">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2rem' }}>
        <div>
          <h1 style={{ fontSize: '1.75rem', fontWeight: 700, marginBottom: '0.25rem' }}>Student Progress</h1>
          <p style={{ color: 'var(--muted-foreground)' }}>Review assessment performance and provide student feedback.</p>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '1.5rem', marginBottom: '2.5rem' }}>
        {stats.map((stat, i) => {
          const Icon = stat.icon;
          return (
            <motion.div 
              key={stat.label}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.1 }}
              className="card" 
              style={{ display: 'flex', alignItems: 'center', gap: '1.25rem' }}
            >
              <div style={{ background: `${stat.color}15`, color: stat.color, padding: '0.75rem', borderRadius: '1rem' }}>
                <Icon size={24} />
              </div>
              <div>
                <p style={{ fontSize: '0.85rem', color: 'var(--muted-foreground)' }}>{stat.label}</p>
                <h3 style={{ fontSize: '1.5rem', fontWeight: 700 }}>{stat.value}</h3>
              </div>
            </motion.div>
          );
        })}
      </div>

      <div className="card" style={{ padding: '0', overflow: 'hidden' }}>
        <div style={{ padding: '1.25rem', borderBottom: '1px solid var(--card-border)', display: 'flex', gap: '1rem' }}>
          <div style={{ position: 'relative', flex: 1 }}>
            <Search size={18} style={{ position: 'absolute', left: '1rem', top: '50%', transform: 'translateY(-50%)', color: 'var(--muted)' }} />
            <input 
              placeholder="Search by student name or assessment..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              style={{ paddingLeft: '2.75rem', background: 'var(--accent)', border: 'none', borderRadius: '0.75rem' }}
            />
          </div>
        </div>

        <div style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
            <thead style={{ background: 'var(--accent)', fontSize: '0.85rem', color: 'var(--muted-foreground)', textTransform: 'uppercase' }}>
              <tr>
                <th style={{ padding: '1rem 1.5rem' }}>Student</th>
                <th style={{ padding: '1rem 1.5rem' }}>Assessment</th>
                <th style={{ padding: '1rem 1.5rem' }}>Score</th>
                <th style={{ padding: '1rem 1.5rem' }}>Status</th>
                <th style={{ padding: '1rem 1.5rem' }}>Date</th>
                <th style={{ padding: '1rem 1.5rem', textAlign: 'right' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map((s) => (
                <tr key={s.id} style={{ borderBottom: '1px solid var(--card-border)' }}>
                  <td style={{ padding: '1.25rem 1.5rem' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                      <div style={{ 
                        width: '32px', height: '32px', background: 'var(--accent)', borderRadius: '50%', 
                        display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 600, fontSize: '0.7rem' 
                      }}>
                        {s.studentName.split(' ').map(n => n[0]).join('')}
                      </div>
                      <span style={{ fontWeight: 600 }}>{s.studentName}</span>
                    </div>
                  </td>
                  <td style={{ padding: '1.25rem 1.5rem' }}>{s.assessmentTitle}</td>
                  <td style={{ padding: '1.25rem 1.5rem' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                      <div style={{ width: '60px', height: '6px', background: 'var(--accent)', borderRadius: '3px', overflow: 'hidden' }}>
                        <div style={{ width: `${s.score}%`, height: '100%', background: s.score >= 70 ? '#10b981' : '#f59e0b' }} />
                      </div>
                      <span style={{ fontSize: '0.9rem', fontWeight: 700 }}>{s.score}%</span>
                    </div>
                  </td>
                  <td style={{ padding: '1.25rem 1.5rem' }}>
                    <span style={{ 
                      padding: '0.2rem 0.6rem', borderRadius: '1rem', fontSize: '0.75rem', fontWeight: 600,
                      background: 
                        s.status === 'Passed' ? 'rgba(16, 185, 129, 0.1)' : 
                        s.status === 'Submitted' ? 'rgba(59, 130, 246, 0.1)' :
                        'rgba(245, 158, 11, 0.1)',
                      color: 
                        s.status === 'Passed' ? '#10b981' : 
                        s.status === 'Submitted' ? '#3b82f6' :
                        '#d97706'
                    }}>
                      {s.status}
                    </span>
                  </td>
                  <td style={{ padding: '1.25rem 1.5rem', color: 'var(--muted-foreground)', fontSize: '0.85rem' }}>{s.date}</td>
                  <td style={{ padding: '1.25rem 1.5rem', textAlign: 'right' }}>
                    <button 
                      onClick={() => handleEvaluate(s)}
                      style={{ 
                        background: 'var(--primary)', color: 'white', padding: '0.5rem 1rem', 
                        borderRadius: '0.5rem', display: 'inline-flex', alignItems: 'center', gap: '0.4rem',
                        fontSize: '0.8rem', fontWeight: 600
                      }}
                    >
                      <Edit3 size={14} />
                      Evaluate
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Valuation Modal */}
      {isModalOpen && (
        <div style={{
          position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
          background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center',
          zIndex: 1000, backdropFilter: 'blur(4px)'
        }}>
          <motion.div 
            initial={{ scale: 0.9, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            style={{
              background: 'white', width: '90%', maxWidth: '700px', maxHeight: '90vh',
              borderRadius: '1.5rem', display: 'flex', flexDirection: 'column', overflow: 'hidden',
              boxShadow: '0 25px 50px -12px rgba(0,0,0,0.25)'
            }}
          >
            {/* Modal Header */}
            <div style={{ padding: '1.5rem', borderBottom: '1px solid var(--card-border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div>
                <h2 style={{ fontSize: '1.25rem', fontWeight: 700 }}>Valuation & Review</h2>
                <p style={{ fontSize: '0.85rem', color: 'var(--muted-foreground)' }}>{evaluatingSubmission?.studentName} - {evaluatingSubmission?.assessmentTitle}</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} style={{ color: 'var(--muted)', background: 'transparent' }}><X size={24} /></button>
            </div>

            {/* Modal Content */}
            <div style={{ flex: 1, overflowY: 'auto', padding: '1.5rem' }}>
              {evaluatingSubmission?.status === 'Pending' ? (
                <div style={{ textAlign: 'center', padding: '2.5rem', background: 'rgba(245, 158, 11, 0.05)', borderRadius: '1rem', color: '#d97706', border: '1px dashed #f59e0b' }}>
                  <Clock size={40} style={{ margin: '0 auto 1rem', opacity: 0.6 }} />
                  <h3 style={{ fontSize: '1.1rem', fontWeight: 600, marginBottom: '0.5rem' }}>Assessment Still Pending</h3>
                  <p style={{ fontSize: '0.85rem' }}>The student has not yet submitted this assessment. Answers will be visible here once they complete the test.</p>
                </div>
              ) : !evaluatingSubmission?.answers ? (
                <div style={{ textAlign: 'center', padding: '2.5rem', background: 'var(--accent)', borderRadius: '1rem', color: 'var(--muted-foreground)' }}>
                  <AlertCircle size={40} style={{ margin: '0 auto 1rem', opacity: 0.5 }} />
                  <h3 style={{ fontSize: '1.1rem', fontWeight: 600, marginBottom: '0.5rem' }}>No Detailed Answers</h3>
                  <p style={{ fontSize: '0.85rem' }}>Detailed individual answer tracking was not available for this session.</p>
                </div>
              ) : (
                <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
                  <h3 style={{ fontSize: '1rem', fontWeight: 600 }}>Answers Review</h3>
                  {evaluatingAssessment?.questions.map((q: any, i: number) => {
                    const studentAnswer = evaluatingSubmission.answers?.[q.id];
                    const isMCQ = q.type === 'MCQ' || (q.options && q.options.length > 0);
                    const isCorrect = manualMarks[q.id];

                    return (
                      <div key={q.id || i} style={{ padding: '1rem', background: 'white', borderRadius: '0.75rem', border: '1px solid var(--card-border)' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.5rem' }}>
                          <p style={{ fontWeight: 600, fontSize: '0.9rem' }}>{i + 1}. {q.text}</p>
                          <div style={{ display: 'flex', gap: '0.5rem' }}>
                             <button 
                               onClick={() => {
                                 const nextMarks = { ...manualMarks, [q.id]: true };
                                 setManualMarks(nextMarks);
                                 // Auto update score
                                 const correctCount = Object.values(nextMarks).filter(Boolean).length;
                                 setValuationScore(Math.round((correctCount / evaluatingAssessment.questions.length) * 100));
                               }}
                               style={{ 
                                 padding: '0.2rem 0.5rem', borderRadius: '0.4rem', fontSize: '0.7rem',
                                 background: isCorrect ? '#ef4444' : '#10b981', color: 'white'
                               }}
                             >
                               {isCorrect ? 'Correct ✓' : 'Mark Correct'}
                             </button>
                             <button 
                               onClick={() => {
                                 const nextMarks = { ...manualMarks, [q.id]: false };
                                 setManualMarks(nextMarks);
                                 const correctCount = Object.values(nextMarks).filter(Boolean).length;
                                 setValuationScore(Math.round((correctCount / evaluatingAssessment.questions.length) * 100));
                               }}
                               style={{ 
                                 padding: '0.2rem 0.5rem', borderRadius: '0.4rem', fontSize: '0.7rem',
                                 background: isCorrect === false ? '#64748b' : '#ef4444', color: 'white'
                               }}
                             >
                               {isCorrect === false ? 'Incorrect ✗' : 'Mark Incorrect'}
                             </button>
                          </div>
                        </div>
                        
                        {isMCQ ? (
                          <div style={{ fontSize: '0.85rem', display: 'flex', flexWrap: 'wrap', gap: '1.5rem', background: '#f8fafc', padding: '1rem', borderRadius: '0.75rem' }}>
                            <div>
                              <p style={{ fontSize: '0.75rem', color: 'var(--muted-foreground)', marginBottom: '0.25rem' }}>Student Answer:</p>
                              <span style={{ color: 'var(--foreground)', fontWeight: 600 }}>
                                {studentAnswer !== undefined ? q.options[studentAnswer] : 'No Answer'}
                              </span>
                            </div>
                            <div>
                              <p style={{ fontSize: '0.75rem', color: 'var(--muted-foreground)', marginBottom: '0.25rem' }}>Reference Answer:</p>
                              <span style={{ color: '#10b981', fontWeight: 600 }}>
                                {q.options[q.correctAnswer]}
                              </span>
                            </div>
                          </div>
                        ) : (
                          <div style={{ fontSize: '0.85rem', background: '#f8fafc', padding: '1rem', borderRadius: '0.75rem' }}>
                            <p style={{ fontSize: '0.75rem', color: 'var(--muted-foreground)', marginBottom: '0.25rem' }}>Student's Answer:</p>
                            <p style={{ fontWeight: 600, whiteSpace: 'pre-wrap' }}>{studentAnswer || <span style={{ fontStyle: 'italic', color: '#94a3b8' }}>No answer provided</span>}</p>
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}

              {/* Valuation Inputs */}
              <div style={{ marginTop: '2.5rem', paddingTop: '2rem', borderTop: '2px dashed var(--card-border)' }}>
                <h3 style={{ fontSize: '1rem', fontWeight: 600, marginBottom: '1.25rem' }}>Set Final Valuation</h3>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1.5rem' }}>
                  <div>
                    <label style={{ display: 'block', fontSize: '0.85rem', marginBottom: '0.5rem', fontWeight: 500 }}>Numeric Score (%)</label>
                      <input 
                        type="number" 
                        min="0" max="100" 
                        value={valuationScore}
                        onChange={(e) => setValuationScore(Math.min(100, Math.max(0, parseInt(e.target.value) || 0)))}
                        style={{ padding: '0.75rem', borderRadius: '0.75rem', background: 'var(--accent)', border: 'none' }}
                      />
                  </div>
                  <div>
                    <label style={{ display: 'block', fontSize: '0.85rem', marginBottom: '0.5rem', fontWeight: 500 }}>Review Status</label>
                    <select 
                      value={valuationStatus}
                      onChange={(e) => setValuationStatus(e.target.value)}
                      style={{ padding: '0.75rem', borderRadius: '0.75rem', background: 'var(--accent)', border: 'none', width: '100%' }}
                    >
                      <option value="Pending">Pending</option>
                      <option value="Passed">Passed</option>
                      <option value="Failed">Failed</option>
                    </select>
                  </div>
                </div>
              </div>
            </div>

            {/* Modal Footer */}
            <div style={{ padding: '1.5rem', borderTop: '1px solid var(--card-border)', background: 'var(--accent)', display: 'flex', justifyContent: 'flex-end', gap: '1rem' }}>
              <button 
                onClick={() => setIsModalOpen(false)}
                style={{ background: 'white', color: 'var(--foreground)', padding: '0.75rem 1.5rem', borderRadius: '0.75rem', fontWeight: 600, border: '1px solid var(--card-border)' }}
              >
                Cancel
              </button>
              <button 
                onClick={handleSaveValuation}
                disabled={isSaving}
                style={{ 
                  background: 'var(--primary)', color: 'white', padding: '0.75rem 2rem', 
                  borderRadius: '0.75rem', fontWeight: 600, display: 'flex', alignItems: 'center', gap: '0.5rem' 
                }}
              >
                {isSaving ? 'Saving...' : (
                  <>
                    <CheckCircle2 size={18} />
                    Complete Valuation
                  </>
                )}
              </button>
            </div>
          </motion.div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { useAuth, UserRole } from '@/context/AuthContext';
import { useSearchParams } from 'next/navigation';
import { motion, AnimatePresence } from 'framer-motion';
import { Mail, Lock, LogIn, Shield, BookOpen, GraduationCap, CheckCircle2, AlertCircle } from 'lucide-react';
import Link from 'next/link';
import { Suspense } from 'react';

function LoginForm() {
  const { login, isLoading } = useAuth();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [success] = useState('');
  const searchParams = useSearchParams();
  const registrationSuccess = searchParams.get('registered') === 'true';

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !password) {
      setError('Please fill in all fields');
      return;
    }
    setError('');
    try {
      await login(email, password);
    } catch (err) {
      console.error(err);
      setError('Login failed. Please check your credentials.');
    }
  };

  const roles = [
    { id: 'admin', label: 'Administrator', icon: Shield, color: '#3b82f6' },
    { id: 'educator', label: 'Educator', icon: BookOpen, color: '#10b981' },
    { id: 'student', label: 'Student', icon: GraduationCap, color: '#8b5cf6' },
  ];

  return (
    <div style={{
      minHeight: '100vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '2rem',
      position: 'relative',
      overflow: 'hidden',
      background: '#f8fafc'
    }}>
      {/* Ethereal Aurora Background (Light) */}
      <div style={{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0, overflow: 'hidden', zIndex: 0 }}>
        <motion.div 
          animate={{ 
            scale: [1, 1.3, 1],
            x: [0, 80, 0],
            y: [0, 40, 0]
          }}
          transition={{ duration: 15, repeat: Infinity, ease: 'linear' }}
          style={{ 
            position: 'absolute', top: '-15%', left: '-5%', width: '60%', height: '60%', 
            background: 'radial-gradient(circle, rgba(59, 130, 246, 0.08) 0%, transparent 70%)', filter: 'blur(100px)' 
          }} 
        />
        <motion.div 
          animate={{ 
            scale: [1.3, 1, 1.3],
            x: [0, -80, 0],
            y: [0, -40, 0]
          }}
          transition={{ duration: 18, repeat: Infinity, ease: 'linear' }}
          style={{ 
            position: 'absolute', bottom: '-15%', right: '-5%', width: '60%', height: '60%', 
            background: 'radial-gradient(circle, rgba(139, 92, 246, 0.08) 0%, transparent 70%)', filter: 'blur(100px)' 
          }} 
        />
      </div>

      <motion.div 
        initial={{ opacity: 0, y: 30 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
        className="premium-card"
        style={{ 
          width: '100%', maxWidth: '480px', padding: '4rem', zIndex: 1,
          background: 'rgba(255, 255, 255, 0.7)',
          backdropFilter: 'blur(20px)',
          border: '1px solid rgba(255, 255, 255, 0.8)',
          boxShadow: '0 25px 80px -15px rgba(0, 0, 0, 0.08), 0 10px 30px -10px rgba(0, 0, 0, 0.04)',
          borderRadius: '2.5rem'
        }}
      >
        <div style={{ textAlign: 'center', marginBottom: '3.5rem' }}>
          <div style={{ 
            width: '80px', height: '80px', borderRadius: '24px', display: 'flex', alignItems: 'center', justifyContent: 'center',
            margin: '0 auto 2rem', color: 'white', 
            background: 'linear-gradient(135deg, #3b82f6 0%, #8b5cf6 100%)',
            boxShadow: '0 15px 30px -5px rgba(59, 130, 246, 0.4)'
          }}>
            <LogIn size={40} />
          </div>
          <h1 style={{ fontSize: '2.5rem', fontWeight: 800, color: '#0f172a', letterSpacing: '-1.5px', marginBottom: '0.75rem' }}>AssessmentTool</h1>
          <p style={{ color: '#64748b', fontSize: '1.1rem', fontWeight: 500 }}>Login to Your Account</p>
        </div>

        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: '1.5rem' }}>
            <label style={{ display: 'block', fontSize: '0.8rem', marginBottom: '0.75rem', fontWeight: 800, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '0.08em' }}>Email</label>
            <div style={{ position: 'relative' }}>
              <Mail size={20} style={{ position: 'absolute', left: '1.25rem', top: '50%', transform: 'translateY(-50%)', color: '#cbd5e1' }} />
              <input
                type="email"
                placeholder="email@example.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                style={{ 
                  padding: '1.1rem 1.25rem 1.1rem 3.5rem', width: '100%', 
                  background: 'white', border: '1px solid #f1f5f9', 
                  borderRadius: '1.25rem', color: '#1e293b', fontSize: '1.1rem', outline: 'none',
                  boxShadow: '0 2px 4px rgba(0,0,0,0.01) inset', transition: 'all 0.3s'
                }}
                required
              />
            </div>
          </div>

          <div style={{ marginBottom: '2.5rem' }}>
            <label style={{ display: 'block', fontSize: '0.8rem', marginBottom: '0.75rem', fontWeight: 800, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '0.08em' }}>Password</label>
            <div style={{ position: 'relative' }}>
              <Lock size={20} style={{ position: 'absolute', left: '1.25rem', top: '50%', transform: 'translateY(-50%)', color: '#cbd5e1' }} />
              <input
                type="password"
                placeholder="••••••••"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                style={{ 
                  padding: '1.1rem 1.25rem 1.1rem 3.5rem', width: '100%', 
                  background: 'white', border: '1px solid #f1f5f9', 
                  borderRadius: '1.25rem', color: '#1e293b', fontSize: '1.1rem', outline: 'none',
                  boxShadow: '0 2px 4px rgba(0,0,0,0.01) inset', transition: 'all 0.3s'
                }}
                required
              />
            </div>
          </div>

          <AnimatePresence>
            {(error || registrationSuccess) && (
              <motion.div 
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: 'auto' }}
                exit={{ opacity: 0, height: 0 }}
                style={{ 
                  color: error ? '#ef4444' : '#10b981', 
                  fontSize: '0.95rem', marginBottom: '1.5rem', textAlign: 'center',
                  padding: '1rem', background: error ? '#fef2f2' : '#f0fdf4',
                  borderRadius: '1rem', border: `1px solid ${error ? '#fee2e2' : '#dcfce7'}`,
                  display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.75rem',
                  fontWeight: 600
                }}
              >
                {registrationSuccess ? <CheckCircle2 size={18} /> : <AlertCircle size={18} />}
                {registrationSuccess ? 'Registration successful. Please log in.' : error}
              </motion.div>
            )}
          </AnimatePresence>

          <motion.button 
            whileHover={{ scale: 1.02, boxShadow: '0 15px 30px -5px rgba(59, 130, 246, 0.4)' }}
            whileTap={{ scale: 0.98 }}
            type="submit" 
            className="btn-primary" 
            style={{ 
              width: '100%', padding: '1.25rem', borderRadius: '1.25rem', fontSize: '1.1rem', fontWeight: 800,
              background: 'linear-gradient(135deg, #3b82f6 0%, #2563eb 100%)', border: 'none',
              boxShadow: '0 10px 20px -5px rgba(37, 99, 235, 0.3)'
            }}
            disabled={isLoading}
          >
            {isLoading ? 'Verifying...' : 'Login'}
          </motion.button>

          <p style={{ textAlign: 'center', marginTop: '2.5rem', fontSize: '1rem', color: '#64748b', fontWeight: 500 }}>
            Don't have an account? <Link href="/register" style={{ color: '#3b82f6', fontWeight: 700, textDecoration: 'none' }}>Register Now</Link>
          </p>
        </form>
      </motion.div>
    </div>
  );
}

export default function LoginPage() {
  return (
    <Suspense fallback={
      <div style={{ 
        minHeight: '100vh', 
        display: 'flex', 
        alignItems: 'center', 
        justifyContent: 'center',
        background: 'linear-gradient(135deg, #f8fafc 0%, #e2e8f0 100%)'
      }}>
        <div className="animate-pulse" style={{ color: 'var(--primary)' }}>Loading...</div>
      </div>
    }>
      <LoginForm />
    </Suspense>
  );
}

